# Key AI theo từng học viên (mahs) — mỗi người nhập key riêng
AI_USER_OVERRIDES: Dict[str, Dict[str, Any]] = {}
def short_plain_text(s: Any, n: int = 160) -> str:
    t = re.sub(r"\s+", " ", clean(s))
    return t if len(t) <= n else t[: max(0, n - 1)] + "…"



# ============================================================
# TIỆN ÍCH CHUẨN HÓA
# ============================================================

def strip_accents(s: Any) -> str:
    s = str(s or "")
    s = unicodedata.normalize("NFD", s)
    return "".join(ch for ch in s if unicodedata.category(ch) != "Mn")


def key_norm(s: Any) -> str:
    s = strip_accents(str(s or "").strip().lower())
    s = s.replace("\u0111", "d").replace("\u0110", "d")  # đ/Đ → d (strip_accents không xử lý)
    s = re.sub(r"\s+", " ", s)
    s = s.replace("_", " ").replace("-", " ")
    return s.strip()


def subject_kind_from_mon(mon: Any) -> str:
    """math | physics | other | '' (không rõ)."""
    k = key_norm(mon)
    if not k:
        return ""
    if "toan" in k or "math" in k:
        return "math"
    if "vat li" in k or "vat ly" in k or "physics" in k or k in ("ly", "vat li"):
        return "physics"
    return "other"


def infer_subject_kind_from_question(q: Dict[str, Any]) -> str:
    """Suy môn khi cột Mon trống — từ metadata/đề bài."""
    kind = subject_kind_from_mon(clean(q.get("Mon", "")))
    if kind:
        return kind
    blob = " ".join(
        clean(q.get(f, ""))
        for f in ("DangBaiTap", "Chuong", "BaiHoc", "CauHoi", "BoDe", "De", "MaDe")
    )
    k = key_norm(blob)
    if any(
        x in k
        for x in (
            "dao dong", "dien tu", "quang hoc", "nhiet", "luc ", "cong suat",
            "vat li", "dong dien", "tu truong", "song",
        )
    ):
        return "physics"
    if any(
        x in k
        for x in (
            "ham so", "phuong trinh", "logarit", "tich phan", "dao ham",
            "luong giac", "hinh hoc", "so phuc", "xac suat", "toan",
            "cotang", "sin ", "cos ", "tan ",
        )
    ):
        return "math"
    return ""


def effective_question_mon(q: Dict[str, Any], catalog_mon: str = "") -> str:
    mon = clean(q.get("Mon", ""))
    if mon:
        return mon
    cat = clean(catalog_mon)
    if cat:
        return cat
    kind = infer_subject_kind_from_question(q)
    if kind == "math":
        return "Toán"
    if kind == "physics":
        return "Vật lí"
    return ""


def question_for_ai_prompt(q: Dict[str, Any], catalog_mon: str = "") -> Dict[str, Any]:
    out = dict(q or {})
    em = effective_question_mon(out, catalog_mon)
    if em and not clean(out.get("Mon")):
        out["Mon"] = em
    return out


def assistant_subject_rules(q: Dict[str, Any]) -> List[str]:
    kind = subject_kind_from_mon(effective_question_mon(q)) or infer_subject_kind_from_question(q)
    if kind == "math":
        return [
            "MÔN HIỆN TẠI: TOÁN HỌC THPT — dùng tư duy, ký hiệu và phương pháp TOÁN.",
            "- KHÔNG giải như Vật lí (lực, điện trở, công suất, dao động cơ…) trừ khi đề thật sự liên môn.",
            "- Nhấn: biến đổi đại số, lượng giác, hàm số, phương trình, hình học, số phức, xác suất…",
            "- Nêu điều kiện xét (MXĐ, góc, miền giá trị) thay vì «đổi đơn vị SI» khi bài không có đại lượng vật lí.",
            "- Phong cách thầy Minh dạy Toán: gọn, chính xác, có bước; gọi học sinh là «em».",
        ]
    if kind == "physics":
        return [
            "MÔN HIỆN TẠI: VẬT LÍ THPT — dùng tư duy, ký hiệu và phương pháp VẬT LÍ.",
            "- Nhấn đổi đơn vị SI, chọn hệ trục/hướng dương, đọc đồ thị, sơ đồ lực/mạch khi cần.",
            "- Dùng đúng công thức vật lí trong chương bài; không giải thuần Toán nếu đề là vật lí.",
        ]
    return [
        f"MÔN: {clean(q.get('Mon')) or 'chưa rõ — suy từ đề, không tự đổi môn'}.",
    ]


def assistant_sys_prompt_for_question(q: Dict[str, Any], *, chat: bool = False) -> str:
    kind = subject_kind_from_mon(effective_question_mon(q)) or infer_subject_kind_from_question(q)
    dang = effective_dang(q)
    dcode = assistant_dang_code(dang)
    role = "trả lời hỏi đáp" if chat else "hướng dẫn"
    dang_note = f"Dạng câu {dcode}: đọc lại đề, gợi ý các bước làm, kết thúc bằng đáp án đúng theo quy ước {dcode}. Không dùng markdown *, ** hoặc bullet dấu sao; mỗi Bước 1, Bước 2... phải ở đoạn riêng."
    if kind == "math":
        return (
            "Bạn là Trợ lý AI thầy Minh — giáo viên Toán THPT. "
            f"Chỉ {role} theo phương pháp Toán; không lẫn Vật lí. {dang_note}"
        )
    if kind == "physics":
        return (
            "Bạn là Trợ lý AI thầy Minh — giáo viên Vật lí THPT. "
            f"Chỉ {role} theo phương pháp Vật lí. {dang_note}"
        )
    return (
        "Bạn là Trợ lý AI thầy Minh trong app luyện đề THPT. "
        f"Chỉ {role}; {dang_note}"
    )


def assistant_dang_code(dang: str) -> str:
    spec = _infographic_dang_spec(dang)
    return spec.get("code", "TN")


def assistant_format_final_answer(q: Dict[str, Any]) -> str:
    """Chuỗi đáp án cuối theo TN / Đ/S / TLN để AI và fallback dùng thống nhất."""
    dang = effective_dang(q)
    raw = clean(q.get("DapAn", ""))
    if not raw:
        return "(chưa có đáp án Sheet cột P)"
    if dang == "Trắc nghiệm":
        c = norm_letter(raw)
        return f"Phương án đúng: {c}" if c else raw
    if dang == "Đúng sai":
        disp = format_tf_answer_display(q)
        return disp or raw
    if dang == "Trả lời ngắn":
        saiso = clean(q.get("SaiSo", ""))
        base = raw
        if saiso:
            return f"{base} (sai số ±{saiso})"
        return base
    return raw


def assistant_dang_prompt_rules(dang: str) -> List[str]:
    code = assistant_dang_code(dang)
    spec = _infographic_dang_spec(dang)
    common = [
        f"LOẠI CÂU BẮT BUỘC: {spec['title']} — {spec['desc']}",
        "- Phải ĐỌC LẠI ĐỀ (tóm tắt đề hỏi gì, dữ kiện chính) trước khi hướng dẫn.",
        "- Gợi ý CÁC BƯỚC LÀM rõ ràng; mỗi Bước 1, Bước 2… xuống một dòng/đoạn riêng; được thay số minh họa từng bước.",
        "- Không dùng markdown dấu * hoặc **; nếu cần liệt kê thì dùng dòng thường, không dùng bullet dấu sao.",
        "- Cuối cùng BẮT BUỘC có mục «Đáp án cuối cùng» đúng quy ước loại câu.",
        "- Đối chiếu đáp án Sheet cột P và lời giải cột R (nếu có); nếu mâu thuẫn thì ưu tiên Sheet.",
    ]
    if dang == "Trắc nghiệm":
        return common + [
            "- TN: một chữ A/B/C/D đúng duy nhất — KHÔNG chọn Đúng/Sai cho từng ý.",
            "- Cuối bài ghi: «Đáp án cuối cùng: [một chữ A/B/C/D]».",
            "- Có thể giải thích ngắn vì sao các phương án khác sai, nhưng không bỏ qua bước suy luận.",
        ]
    if dang == "Đúng sai":
        return common + [
            "- Đ/S: bốn mệnh đề A–D, mỗi ý Đúng hoặc Sai — KHÔNG chỉ chọn một chữ A/B/C/D.",
            "- Cuối bài ghi: «Đáp án cuối cùng: A=Đúng · B=Sai · …» (đủ các ý có trong đề).",
            "- Nên lần lượt phân tích từng mệnh đề A, B, C, D trước khi chốt.",
        ]
    if dang == "Trả lời ngắn":
        return common + [
            "- TLN: học sinh nhập số/biểu thức — KHÔNG có phương án A/B/C/D (trừ khi đề có thêm gợi ý).",
            "- Cuối bài ghi: «Đáp án cuối cùng: [số hoặc biểu thức]»; nêu sai số (cột Q) nếu Sheet có.",
            "- Ghi đơn vị (nếu đề yêu cầu) và làm tròn theo quy ước đề.",
        ]
    return common + [f"- Dạng {code}: trình bày đủ bước và kết quả cuối theo Sheet."]


def assistant_note_layout_block(dang: str) -> List[str]:
    code = assistant_dang_code(dang)
    if dang == "Trắc nghiệm":
        ans_fmt = "Đáp án cuối cùng: [một chữ A/B/C/D]"
    elif dang == "Đúng sai":
        ans_fmt = "Đáp án cuối cùng: A=Đúng · B=Sai · C=… · D=…"
    elif dang == "Trả lời ngắn":
        ans_fmt = "Đáp án cuối cùng: [số/biểu thức, kèm đơn vị/sai số nếu có]"
    else:
        ans_fmt = "Đáp án cuối cùng: …"
    return [
        "BỐ CỤC TRẢ LỜI BẮT BUỘC:",
        f"1. Đọc lại đề ({code}): tóm tắt đề hỏi gì, dữ kiện chính.",
        "2. Dạng bài / kiến thức: …",
        "3. Các bước làm: mỗi bước xuống dòng riêng, dạng Bước 1: … / Bước 2: … / Bước 3: … (có thể thay số).",
        "4. Lưu ý & bẫy dễ sai: … (không dùng bullet dấu sao).",
        f"5. {ans_fmt}",
    ]


def assistant_question_from_session(
    store: Any, ses: Dict[str, Any], qs: List[Dict[str, Any]], idx: int
) -> Dict[str, Any]:
    q = dict(qs[idx])
    cat = catalog_find_by_made(store, clean(ses.get("made", "")))
    catalog_mon = clean(cat.get("Mon", "")) if cat else ""
    return question_for_ai_prompt(q, catalog_mon)


def assistant_fallback_note(q: Dict[str, Any]) -> str:
    return assistant_sheet_fallback_note(q)


def assistant_sheet_fallback_note(q: Dict[str, Any]) -> str:
    """Fallback bám Sheet — ưu tiên lời giải cột R thay vì mẫu chung chung."""
    lg = clean(q.get("LoiGiai", ""))
    dang = effective_dang(q)
    code = assistant_dang_code(dang)
    ans = assistant_format_final_answer(q)
    cau = clean(q.get("CauHoi", ""))
    if not is_admin():
        kind = subject_kind_from_mon(effective_question_mon(q)) or infer_subject_kind_from_question(q)
        cond = "kiểm tra điều kiện và biến đổi tương đương" if kind == "math" else "đổi đơn vị SI và kiểm tra điều kiện áp dụng"
        return "\n".join([
            f"1. Đọc lại đề ({code}): {cau[:200] or '(xem đề trên)'}{'…' if len(cau) > 200 else ''}",
            f"2. Dạng bài: {clean(q.get('DangBaiTap', '')) or 'nhận dạng theo chương bài'}",
            "3. Hướng làm: gạch dữ kiện, chọn công thức phù hợp, thay số từng bước.",
            f"4. Tự kiểm tra: {cond}; so lại loại câu TN/Đ/S/TLN trước khi chọn.",
        ])
    if lg:
        lg_show = lg[:2200] + ("…" if len(lg) > 2200 else "")
        parts = [
            f"1. Đọc lại đề ({code}):",
            cau or "(xem đề trên)",
            "",
            f"2. Các bước làm (theo lời giải Sheet cột R):",
            lg_show,
            "",
            f"3. Đáp án cuối cùng: {ans}",
        ]
        return "\n".join(parts)
    kind = subject_kind_from_mon(effective_question_mon(q)) or infer_subject_kind_from_question(q)
    cond = "MXĐ, miền giá trị, đơn vị góc" if kind == "math" else "đổi đơn vị SI, điều kiện áp dụng"
    steps = (
        "Xác định điều kiện → biến đổi → suy luận → kiểm tra"
        if kind == "math"
        else "Gạch dữ kiện → đổi đơn vị nếu cần → áp dụng công thức → kiểm tra"
    )
    return "\n".join([
        f"1. Đọc lại đề ({code}): {cau[:200] or '(xem đề trên)'}{'…' if len(cau) > 200 else ''}",
        f"2. Dạng bài: {clean(q.get('DangBaiTap', '')) or 'nhận dạng theo chương bài'}",
        f"3. Các bước làm: {steps}.",
        f"4. Lưu ý: {cond}.",
        "5. Bẫy dễ sai: đọc vội đề, bỏ điều kiện, nhầm loại câu TN/Đ/S/TLN.",
        f"6. Đáp án cuối cùng: {ans}",
    ])


def assistant_ensure_final_answer_line(txt: str, q: Dict[str, Any]) -> str:
    """Chốt dòng đáp án cuối khớp Sheet cột P."""
    t = clean(txt)
    if not t:
        return t
    ans = assistant_format_final_answer(q)
    if not ans or ans.startswith("(chưa"):
        return t
    final_line = f"Đáp án cuối cùng: {ans}"
    pat = re.compile(r"(?im)^\s*đáp\s*án\s*cuối\s*cùng\s*[:：].*$")
    kept = [ln for ln in t.splitlines() if not pat.match(ln)]
    body = "\n".join(kept).rstrip()
    return f"{body}\n\n{final_line}" if body else final_line


def assistant_gemini_models(cfg: Optional[Dict[str, Any]] = None) -> List[str]:
    cfg = cfg or ai_runtime_config()
    primary = (
        clean(cfg.get("gemini_model"))
        or clean(os.environ.get("ASSISTANT_GEMINI_MODEL", ""))
        or DEFAULT_ASSISTANT_GEMINI_MODEL
    )
    raw = [primary, DEFAULT_ASSISTANT_GEMINI_MODEL, DEFAULT_GEMINI_ADMIN_MODEL] + GEMINI_HINT_MODEL_FALLBACKS
    out: List[str] = []
    seen: set = set()
    for m in raw:
        m = clean(m)
        if m and m not in seen:
            seen.add(m)
            out.append(m)
    return out


def assistant_provider_try_order() -> List[str]:
    """Trợ lý VIP/SVIP chỉ dùng Gemini; OpenAI dành cho ADMIN."""
    if not is_admin():
        return ["GEMINI"]
    oa_pool = bool(load_ai_keys_from_env("OPENAI"))
    if oa_pool:
        return ["OPENAI", "GEMINI"]
    return ["GEMINI"]


def assistant_run_vip_ai(
    q: Dict[str, Any],
    sys_prompt: str,
    user_prompt: str,
    *,
    max_tokens: int,
    temp: float,
    gemini_only: bool = False,
) -> Tuple[str, int, str, str, str]:
    """Gọi AI học tập: mặc định theo cấu hình; gemini_only=True chỉ dùng Gemini/key người dùng."""
    cfg = ai_runtime_config()
    vision = prepare_question_vision(q)
    img_b64 = vision.get("image_b64", "") if vision.get("vision_ready") else ""
    img_mime = vision.get("image_mime", "") if vision.get("vision_ready") else ""
    sys_use = sys_prompt
    if img_b64:
        sys_use += " Có ẢNH MINH HỌA đính kèm — đọc hình/đồ thị trước khi phân tích."

    openai_keys = load_ai_keys("OPENAI") if is_admin() and not gemini_only else []
    gemini_keys = load_ai_keys("GEMINI")
    model_openai = clean(cfg.get("openai_model") or DEFAULT_OPENAI_HINT_MODEL) or DEFAULT_OPENAI_HINT_MODEL
    oa_model = (
        clean(os.environ.get("OPENAI_VISION_MODEL", DEFAULT_OPENAI_VISION_MODEL))
        if img_b64
        else model_openai
    )
    gemini_models = assistant_gemini_models(cfg)
    if img_b64:
        gv = clean(os.environ.get("GEMINI_VISION_MODEL", DEFAULT_GEMINI_VISION_MODEL)) or DEFAULT_GEMINI_VISION_MODEL
        gemini_models = [gv] + [m for m in gemini_models if m != gv]

    last_error = ""

    def _try_gemini() -> Tuple[str, int, str, str]:
        nonlocal last_error
        for idx, api_key in enumerate(gemini_keys, start=1):
            for gm in gemini_models:
                txt, _finish, err = _gemini_hint_call(
                    api_key,
                    gm,
                    sys_use,
                    user_prompt,
                    max_tokens,
                    temp,
                    timeout=40 if img_b64 else 34,
                    image_b64=img_b64,
                    image_mime=img_mime,
                )
                if err:
                    last_error = err
                    continue
                if clean(txt):
                    return clean(txt), idx, "GEMINI", gm
        return "", 0, "GEMINI", ""

    def _try_openai() -> Tuple[str, int, str, str]:
        nonlocal last_error
        for idx, api_key in enumerate(openai_keys, start=1):
            txt, _finish, err = _openai_chat_call(
                api_key,
                oa_model,
                sys_use,
                user_prompt,
                max_tokens,
                temp,
                timeout=42 if img_b64 else 36,
                image_b64=img_b64,
                image_mime=img_mime,
            )
            if err:
                last_error = err
                if _is_quota_or_rate_error(err):
                    break
                continue
            if clean(txt):
                return clean(txt), idx, "OPENAI", oa_model
        return "", 0, "OPENAI", oa_model

    provider_order = ["GEMINI"] if gemini_only else assistant_provider_try_order()
    for prov in provider_order:
        if prov == "GEMINI" and gemini_keys:
            txt, idx, used, model = _try_gemini()
            if txt:
                return txt, idx, used, model, ""
        elif prov == "OPENAI" and openai_keys:
            txt, idx, used, model = _try_openai()
            if txt:
                return txt, idx, used, model, ""

    return "", 0, "", "", last_error or "AI chưa phản hồi"


def assistant_compact_sys_prompt(q: Dict[str, Any], *, chat: bool = False) -> str:
    kind = subject_kind_from_mon(effective_question_mon(q)) or infer_subject_kind_from_question(q)
    dcode = assistant_dang_code(effective_dang(q))
    subject = "Toán" if kind == "math" else ("Vật lí" if kind == "physics" else "THPT")
    role = "trả lời hỏi thêm" if chat else "giải bài"
    return (
        f"Bạn là thầy Minh dạy {subject}. {role.capitalize()} câu {dcode}: "
        "đọc đề, các bước tính CỤ THỂ (ghi công thức, thay số từ đề), chốt đáp án cuối đúng loại "
        f"{dcode}. Tiếng Việt. Công thức trong $...$. Không dùng markdown *, ** hoặc bullet dấu sao. Mỗi Bước 1, Bước 2... phải xuống dòng riêng."
    )


def build_ai_assistant_compact_prompt(
    q: Dict[str, Any],
    user_answer: Any = "",
    *,
    chat_message: str = "",
    messages: Any = None,
) -> str:
    dang = effective_dang(q)
    code = assistant_dang_code(dang)
    ref = assistant_format_final_answer(q)
    block = build_ai_question_block(
        q, user_answer, include_sheet_answer=True, include_loigiai=False
    )
    if dang == "Trắc nghiệm":
        ans_rule = "Đáp án cuối cùng: một chữ A/B/C/D"
    elif dang == "Đúng sai":
        ans_rule = "Đáp án cuối cùng: A=Đúng · B=Sai · … (đủ các ý có trong đề)"
    else:
        ans_rule = "Đáp án cuối cùng: số hoặc biểu thức (kèm đơn vị nếu có)"
    lg = clean(q.get("LoiGiai", ""))
    lg_part = ""
    if lg and not chat_message:
        lg_part = (
            "\n\nLời giải Sheet (cột R) — trình bày lại các bước, không bỏ phép tính:\n"
            + (lg[:1600] + ("…" if len(lg) > 1600 else ""))
        )
    lines = [
        f"Giải câu {code} — BẮT BUỘC có bước tính từ số trong đề (không chỉ liệt kê chung chung).",
        "",
        "Bố cục:",
        "1. Đọc lại đề (1–2 câu)",
        "2. Các bước làm: mỗi bước xuống dòng riêng: Bước 1: … / Bước 2: … / Bước 3: … (công thức + thay số)",
        f"3. {ans_rule} — khớp Sheet: {ref}",
        "Không dùng markdown dấu * hoặc **. Nếu có mục «Trong đó», mỗi đại lượng xuống một dòng riêng.",
        "",
        block,
    ]
    if lg_part:
        lines.append(lg_part)
    if chat_message:
        hist_lines: List[str] = []
        if isinstance(messages, list):
            for it in messages[-6:]:
                if not isinstance(it, dict):
                    continue
                role = clean(it.get("role", ""))
                text = clean(it.get("text", it.get("content", "")))[:500]
                if not text:
                    continue
                if role == "user":
                    hist_lines.append(f"Học sinh: {text}")
                elif role in ("assistant", "bot"):
                    hist_lines.append(f"Trợ lý: {text}")
        lines.extend(["", "LỊCH SỬ CHAT:", "\n".join(hist_lines) if hist_lines else "(chưa có)"])
        lines.extend(["", "Học sinh hỏi thêm:", clean(chat_message)[:800]])
    return "\n".join(lines)


def assistant_no_keys_message(q: Dict[str, Any]) -> str:
    tail = assistant_sheet_fallback_note(q)
    key_hint = (
        "ADMIN: cấu hình OPENAI_API_KEY/GEMINI_API_KEY trên Render hoặc lưu key ADMIN."
        if is_admin()
        else "VIP/SVIP: mục lục → 🔑 Key AI của tôi → dán key Gemini (AIza... hoặc AQ...) → Lưu."
    )
    return "\n".join([
        "⚠️ Chưa có key AI — không giải tự động được.",
        key_hint,
        "",
        tail,
    ])


def assistant_wrap_fallback_note(q: Dict[str, Any], ai_error: str) -> str:
    body = assistant_sheet_fallback_note(q)
    err = clean(ai_error) or "AI không phản hồi"
    if clean(q.get("LoiGiai", "")):
        head = f"⚠️ AI tạm lỗi ({err[:120]}). Đang hiển thị lời giải Sheet:"
    else:
        head = (
            f"⚠️ AI chưa giải được ({err[:120]}). "
            "Đang hiển thị khung tạm — bấm 🔄 hoặc nạp key Gemini trong 🔑 Key AI của tôi."
        )
    return head + "\n\n" + body


def assistant_invoke_ai(
    q: Dict[str, Any],
    user_answer: Any,
    *,
    chat: bool = False,
    chat_message: str = "",
    messages: Any = None,
    max_tokens: int,
) -> Tuple[str, int, str, str, str]:
    """Thử prompt đầy đủ rồi prompt gọn; trả về (text, key_idx, provider, model, error)."""
    cfg = ai_runtime_config()
    if not cfg.get("has_keys"):
        return "", 0, "FALLBACK", "", "Chưa có key AI (GEMINI_API_KEY hoặc key cá nhân VIP)"

    if chat:
        sys_full = assistant_sys_prompt_for_question(q, chat=True)
        user_full = build_ai_assistant_chat_prompt(q, chat_message, messages, user_answer)
        sys_compact = assistant_compact_sys_prompt(q, chat=True)
        user_compact = build_ai_assistant_compact_prompt(
            q, user_answer, chat_message=chat_message, messages=messages
        )
    else:
        sys_full = assistant_sys_prompt_for_question(q, chat=False)
        user_full = build_ai_assistant_note_prompt(q, user_answer)
        sys_compact = assistant_compact_sys_prompt(q, chat=False)
        user_compact = build_ai_assistant_compact_prompt(q, user_answer)

    sanitize = _sanitize_assistant_chat_text if chat else _sanitize_assistant_note_text
    attempts = [
        (sys_full, user_full, max_tokens, 0.12),
        (sys_compact, user_compact, min(max_tokens, 1100), 0.1),
    ]
    last_error = ""
    for sys_p, user_p, mtok, temp in attempts:
        txt, idx, used, model, err = assistant_run_vip_ai(
            q, sys_p, user_p, max_tokens=mtok, temp=temp
        )
        last_error = err or last_error
        txt = sanitize(txt)
        if txt and not is_admin():
            txt = _strip_student_final_answer_text(txt)
        if txt:
            if is_admin():
                txt = assistant_ensure_final_answer_line(txt, q)
            return txt, idx, used, model, ""
    return "", 0, "", "", last_error


def assistant_fallback_chat(q: Dict[str, Any]) -> str:
    dang = effective_dang(q)
    code = assistant_dang_code(dang)
    if not is_admin():
        return "\n".join([
            f"Em đọc lại đề ({code}) và gạch dữ kiện trước.",
            "Viết công thức chính, thay số theo từng bước rồi tự so với phương án/kết quả.",
            "Nếu còn kẹt, hãy hỏi cụ thể bước nào em chưa hiểu.",
        ])
    ans = assistant_format_final_answer(q)
    return "\n".join([
        f"Em đọc lại đề ({code}) và gạch dữ kiện trước.",
        "Làm lần lượt từng bước; hỏi thầy cụ thể bước nào em kẹt.",
        f"Đáp án cuối cùng (tham chiếu Sheet): {ans}",
    ])


_ROMAN_CHAPTER = {
    "i": 1, "ii": 2, "iii": 3, "iv": 4, "v": 5,
    "vi": 6, "vii": 7, "viii": 8, "ix": 9, "x": 10,
}


def extract_lesson_number(s: Any) -> int:
    t = key_norm(s)
    m = re.search(r"\bbai\s*(\d+)\b", t)
    if m:
        return int(m.group(1))
    m = re.search(r"^(\d+)\b", t)
    if m:
        return int(m.group(1))
    return 9999


def extract_chapter_number(s: Any) -> int:
    t = key_norm(s)
    m = re.search(r"\bchuong\s*(viii|vii|vi|iv|iii|ii|ix|x|i|\d+)\b", t)
    if m:
        token = m.group(1)
        if token.isdigit():
            return int(token)
        return _ROMAN_CHAPTER.get(token, 9999)
    m = re.search(r"^(\d+)\b", t)
    if m:
        return int(m.group(1))
    return 9999


def catalog_sort_key(item: Dict[str, Any]) -> Tuple[Any, ...]:
    bai = clean(item.get("BaiHoc", "")) or clean(item.get("De", ""))
    return (
        key_norm(item.get("Mon", "")),
        key_norm(item.get("Lop", "")),
        extract_chapter_number(item.get("Chuong", "")),
        key_norm(item.get("Chuong", "")),
        extract_lesson_number(bai),
        key_norm(bai),
        key_norm(item.get("BoDe", "")),
    )


def sort_catalog_items(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    return sorted(items, key=catalog_sort_key)


def sort_field_values(field: str, values: List[str]) -> List[str]:
    if field == "BaiHoc":
        return sorted(values, key=lambda v: (extract_lesson_number(v), key_norm(v)))
    if field == "Chuong":
        return sorted(values, key=lambda v: (extract_chapter_number(v), key_norm(v)))
    return sorted(values, key=key_norm)


def clean(v: Any) -> str:
    s = str(v or "").replace("\r\n", "\n").replace("\r", "\n").strip()
    if re.fullmatch(r"\d+\.0", s):
        s = s[:-2]
    return s


def safe_next_url(raw: Any) -> str:
    u = clean(raw)
    if not u or not u.startswith("/") or u.startswith("//"):
        return ""
    return u


_LATEX_VN_BREAK = (
    r"thỏa|mãn|phương|trình|nên|điểm|thuộc|mặt|phẳng|khẳng|tọa|độ|sai|đúng",
)


def _fix_plain_text_gaps(s: str) -> str:
    if not s:
        return s
    s = re.sub(r"(\d)([Nn]ên|[Đđ]iểm)", r"\1 \2", s)
    s = re.sub(r"(\))([A-Za-zÀ-ỹĐđ])", r"\1 \2", s)
    return s


def _fix_one_math_inner(inner: str) -> str:
    if not inner:
        return inner
    # $(M)(4;5;2) → $(M)$ $(4;5;2)$
    inner = re.sub(r"\)\s*\((\d[\d;\s,.\-]*)\)", r")$ $(\1)$", inner)
    inner = re.sub(
        r"\$\(([^)]+)\)(thuộc|mặt|phẳng|nên|điểm)",
        r"$(\1)$ $\2",
        inner,
        flags=re.I,
    )
    # (M)thuộc / (M)nên (không có $ giữa hai cụm)
    inner = re.sub(
        rf"\(([^)]+)\)({_LATEX_VN_BREAK})",
        r"(\1)$ $\2",
        inner,
        flags=re.I,
    )
    inner = re.sub(
        rf"(=[\d.\-+]+)\s*({_LATEX_VN_BREAK})",
        r"\1$ $\2",
        inner,
        flags=re.I,
    )
    inner = re.sub(
        rf"(\))({_LATEX_VN_BREAK})",
        r"\1 \2",
        inner,
        flags=re.I,
    )
    inner = re.sub(r"(\d)([A-Za-zÀ-ỹĐđ][a-zà-ỹà-ỹ]{2,})", r"\1 \2", inner)
    inner = re.sub(r"(\))([A-Za-zÀ-ỹĐđ][a-zà-ỹà-ỹ]{2,})", r"\1 \2", inner)
    inner = re.sub(r"\(\((\\?[a-zA-Z]+)\)\)", r"\1", inner)
    # Dấu } thừa sau mũ: 10^{5}}Pa → 10^{5}\,\text{Pa}
    inner = re.sub(r"(\d+)\^\{([^{}]+)\}\}+", r"\1^{\2}", inner)
    inner = re.sub(
        r"(\d+)\^\{([^{}]+)\}(Pa|kPa|atm|bar)\.?",
        r"\1^{\2}\\,\\text{\3}.",
        inner,
        flags=re.I,
    )
    inner = re.sub(
        r"^\((\d+\^\{[^{}]+\}\\,\\text\{Pa\}\.?)\)\.?$",
        r"\1.",
        inner,
        flags=re.I,
    )
    inner = re.sub(
        r"^\((\d+\^\{[^{}]+\}\\,\\text\{Pa\}\.?)\.?$",
        r"\1.",
        inner,
        flags=re.I,
    )
    inner = re.sub(r"\\text\{cm\}\^\{3\}\}+", r"\\text{cm}^{3}", inner)
    inner = re.sub(r"\^\{([^{}]+)\}\}+", r"^{\1}", inner)
    # c{{m}^{3}} / cm^3 dính số
    inner = re.sub(r"(\d+)\s*c\{\{?\s*m\s*\}\}?\^\{3\}", r"\1\\,\\text{cm}^{3}", inner, flags=re.I)
    inner = re.sub(r"\\acute\{\\mathrm\{i\}\}", "í", inner, flags=re.I)
    inner = re.sub(
        r"\\text\{\s*([^}]*?)\s*\}\s*í\s*\\text\{\s*t\s*\}",
        r"\\text{\1ít}",
        inner,
        flags=re.I,
    )
    inner = re.sub(r"\s+\^\{", "^{", inner)
    inner = re.sub(r"(\d)\s+\^", r"\1^", inner)
    return inner


def _latex_dollar_count(t: str) -> int:
    """Đếm $ inline (bỏ qua $$ display)."""
    n, i, L = 0, 0, len(t)
    while i < L:
        if t[i] == "$" and i + 1 < L and t[i + 1] == "$":
            i += 2
            continue
        if t[i] == "$":
            n += 1
        i += 1
    return n


def _latex_structure_ok(t: str) -> bool:
    """True nếu $ cân bằng và không còn lệnh \\... lẻ ngoài khối $...$."""
    if not t:
        return True
    if _latex_dollar_count(t) % 2 != 0:
        return False
    plain = t
    plain = re.sub(r"\$\$[^$]*\$\$", "", plain)
    plain = re.sub(r"\$[^$]*\$", "", plain)
    if re.search(r"\\[a-zA-Z]", plain):
        return False
    return True


def _is_orphan_math_segment(s: str) -> bool:
    """Đoạn giữa hai khối $...$ chỉ là công thức (không phải câu tiếng Việt)."""
    s = clean(s)
    if not s:
        return False
    if re.search(r"[À-ỹĐđ]{3,}", s):
        return False
    if re.search(r"\\[a-zA-Z]", s):
        return True
    if re.search(r"[=_^{}\\]", s) and not re.search(r"[A-Za-zÀ-ỹĐđ]{4,}", s):
        return True
    return False


def _merge_equiv_chain_math(t: str) -> str:
    """$\\sin 2x=1$\\Leftrightarrow 2x=...$\\Leftrightarrow x=...$ → một khối $...$."""
    if not t or "$" not in t:
        return t
    prev = None
    while prev != t:
        prev = t

        def _repl(m: re.Match) -> str:
            mid = m.group(2)
            if not _is_orphan_math_segment(mid):
                return m.group(0)
            a = m.group(1)[1:-1].strip()
            b = m.group(3)[1:-1].strip()
            return f"${a}{mid.strip()}{b}$"

        t = re.sub(
            r"(\$[^$\n]+?\$)([^$]+?)(\$[^$\n]+?\$)",
            _repl,
            t,
            count=1,
        )
    return t


def _merge_adjacent_inline_math(t: str) -> str:
    """Gộp $...$ $...$ liền nhau (chỉ khoảng trắng giữa) — tránh MathJax lỗi."""
    if not t or "$" not in t:
        return t

    def _repl(m: re.Match) -> str:
        gap = m.group(2)
        if re.search(r"[A-Za-zÀ-ỹĐđ]", gap):
            return m.group(0)
        a = m.group(1)[1:-1].strip()
        b = m.group(3)[1:-1].strip()
        sep = " " if gap.strip() else ""
        return f"${a}{sep}{b}$"

    prev = None
    while prev != t:
        prev = t
        t = re.sub(
            r"(\$[^$\n]+?\$)(\s+)(\$[^$\n]+?\$)",
            _repl,
            t,
        )
    return t


def _trim_inline_math_spaces(t: str) -> str:
    """Bỏ khoảng trắng thừa trong $...$ — tránh rule gỡ $ nhầm khi có « $ »."""
    if not t or "$" not in t:
        return t
    return re.sub(r"\$([^$\n]+?)\$", lambda m: f"${m.group(1).strip()}$", t)


def _fix_surplus_dollar_signs(t: str) -> str:
    """Gỡ $ thừa / lệch cặp — lỗi Word/Sheet hay gặp nhất."""
    if not t or "$" not in t:
        return t
    t = _merge_adjacent_inline_math(t)
    t = _trim_inline_math_spaces(t)
    # $$$... → $$ hoặc $
    t = re.sub(r"\${3,}", "$$", t)
    # $$...$$ một dòng ngắn (inline lỡ gõ $$) → $...$
    t = re.sub(r"\$\$([^$\n]{1,160}?)\$\$", r"$\1$", t)
    # $$...$ hoặc $...$$
    t = re.sub(r"\$\$([^$\n]+?)\$(?!\$)", r"$\1$", t)
    t = re.sub(r"\$([^$\n]+?)\$\$(?!\$)", r"$\1$", t)
    # $..$ rồi còn $ dính ngay sau
    t = re.sub(r"(\$[^$\n]+?\$)\$+", r"\1", t)
    # $ $10^{5}$ → $10^{5}$ (sau merge_adjacent — không còn $...$ $...$)
    t = re.sub(r"\$\s+\$(?=[^$\n])", "$", t)
    # $ $ thật sự rỗng
    t = re.sub(r"\$\s+\$(?=\s|$)", " ", t)
    t = re.sub(r"\$\s*\$", " ", t)
    # KHÔNG gỡ (?<=\s)$(?=\s) — xóa nhầm $ đóng khi «...$ nên $...»
    # KHÔNG gỡ $ trước dấu câu — sẽ làm hỏng $20$, $H$… trong lời giải dài
    # .$ / ,$ rác sau công thức (giữ $10^{5}$.)
    t = re.sub(r"(\$[^$\n]+?\$)\.(\$)(?=\s|$|[A-Za-zÀ-ỹĐđ])", r"\1.", t)
    t = re.sub(r"(\$[^$\n]+?\$)([,.;:])\$(?=\s|$)", r"\1\2", t)
    # Chỉ gỡ $ lẻ cuối chuỗi khi số $ lẻ (mở chưa đóng) — KHÔNG gỡ $ đóng hợp lệ ($...$)
    if t.endswith("$") and _latex_dollar_count(t) % 2 == 1:
        t = t[:-1]
    return t


def _fix_merged_inline_math(t: str) -> str:
    if "$" not in t:
        return _fix_plain_text_gaps(t)
    out, i = [], 0
    n = len(t)
    while i < n:
        if t[i] != "$":
            d1 = t.find("$", i)
            if d1 < 0:
                out.append(_fix_plain_text_gaps(t[i:]))
                break
            out.append(_fix_plain_text_gaps(t[i:d1]))
            i = d1
            continue
        # Giữ khối display $$ ... $$
        if i + 1 < n and t[i + 1] == "$":
            end = t.find("$$", i + 2)
            if end >= 0:
                out.append(t[i : end + 2])
                i = end + 2
                continue
        d2 = t.find("$", i + 1)
        if d2 < 0:
            rest = t[i + 1 :]
            if rest.strip() and ("\\" in rest or "{" in rest):
                out.append(f"${_fix_one_math_inner(rest)}$")
            else:
                out.append(_fix_plain_text_gaps(rest))
            break
        inner = t[i + 1 : d2]
        if not inner.strip():
            i = d2 + 1
            continue
        while d2 + 1 < n and t[d2 + 1] == "$" and (d2 + 2 >= n or t[d2 + 2] != "$"):
            d2 += 1
        inner = _fix_one_math_inner(inner)
        out.append(f"${inner}$")
        i = d2 + 1
    return "".join(out)


def _strip_latex_list_markup(t: str) -> str:
    t = re.sub(r"\\begin\s*\{\s*enumerate\s*\}", "", t, flags=re.I)
    t = re.sub(r"\\end\s*\{\s*enumerate\s*\}", "", t, flags=re.I)
    t = re.sub(r"\\begin\s*\{\s*itemize\s*\}", "", t, flags=re.I)
    t = re.sub(r"\\end\s*\{\s*itemize\s*\}", "", t, flags=re.I)
    t = re.sub(r"\\begin\s*\{\s*itemchoice\s*\}", "", t, flags=re.I)
    t = re.sub(r"\\end\s*\{\s*itemchoice\s*\}", "", t, flags=re.I)
    t = re.sub(r"(?:^|\n)\s*•\s*ch\s+", "\n• ", t, flags=re.I)
    t = re.sub(r"•\s*ch\s+", "• ", t, flags=re.I)
    t = re.sub(r"\\item\s*", "\n• ", t, flags=re.I)
    t = re.sub(r"\\item(?=[A-Za-zÀ-ỹĐđ])", "\n• ", t, flags=re.I)
    return t


_LATEX_UNITS_BETWEEN_MATH = (
    r"rad|deg|m|km|cm|mm|μm|nm|"
    r"s|ms|min|h|"
    r"kg|g|mg|"
    r"N|J|W|Pa|kPa|MPa|"
    r"Hz|V|A|Ω|mol"
)


def _merge_broken_dfrac_sqrt(t: str) -> str:
    """$\\cot 3x=-\\dfrac{1}$ $(\\sqrt{3})$ → $\\cot 3x=-\\dfrac{1}{\\sqrt{3}}$."""
    if not t or "$" not in t:
        return t
    prev = None
    while prev != t:
        prev = t
        t = re.sub(
            r"(\$[^$\n]*?-?)\\dfrac\{(\d+)\}\$\s*\$\(\\sqrt\{([^}]+)\}\)\$",
            r"\1\\dfrac{\2}{\\sqrt{\3}}$",
            t,
        )
    return re.sub(r"\$\(\s*\\", r"$\\", t)


def _merge_unit_between_math(t: str) -> str:
    """$\\frac{3\\pi}{4}$ rad$=\\left(... → $\\frac{3\\pi}{4}\\,\\mathrm{rad}=\\left(...$"""
    if not t or "$" not in t:
        return t
    units = _LATEX_UNITS_BETWEEN_MATH

    def _repl(m: re.Match) -> str:
        a = m.group(1)[1:-1].strip()
        u = m.group(2).strip()
        b = m.group(3)[1:-1].strip()
        if not b.startswith("="):
            return m.group(0)
        inner = f"{a}\\,\\mathrm{{{u}}}{b}"
        return f"${_fix_one_math_inner(inner)}$"

    prev = None
    while prev != t:
        prev = t
        t = re.sub(
            rf"(\$[^$\n]+?\$)\s*({units})\s*(\$[^$\n]*=[^$\n]*\$)",
            _repl,
            t,
            flags=re.I,
        )
    return t


def _fix_math_bs_in_pairs(t: str) -> str:
    def _fix_math_bs(m: re.Match) -> str:
        inner = m.group(1).replace("\\\\", "\\")
        return f"${inner}$"
    return re.sub(r"\$([^$]+)\$", _fix_math_bs, t)


def _latex_needs_heavy_normalize(t: str) -> bool:
    """Chỉ chạy gộp khối $ / sửa Word khi text thật sự lỗi — tránh phá prose tiếng Việt."""
    if not t:
        return False
    if re.search(r"\\(?:item|begin\s*\{enumerate|begin\s*\{itemize|begin\s*\{itemchoice|acute)", t, re.I):
        return True
    if re.search(r"•\s*ch\s+", t, re.I):
        return True
    if re.search(
        rf"\$[^$\n]+\$\s*(?:{_LATEX_UNITS_BETWEEN_MATH})\s*\$",
        t,
        re.I,
    ):
        return True
    if re.search(r"\$\{|\$\$[^$]", t):
        return True
    if re.search(r"\$\s+\$(?=[^$\n])", t):
        return True
    if re.search(
        r"\$[^$\n]*\$[^$]*\\(?:Leftrightarrow|Rightarrow|leftrightarrow|dfrac|tfrac|frac|sqrt|sin|cos|tan|cot|log|ln|pi|alpha|beta|theta)",
        t,
        re.I,
    ):
        return True
    if not _latex_structure_ok(t):
        return True
    return False


def _latex_convert_robot_text_cmds(t: str) -> str:
    """Chuyển lệnh văn bản sách robot/TLH (\\lq, \\rq, \\indam…) sang Unicode."""
    if not t or "\\" not in t:
        return t
    t = re.sub(r"\\lq\s*\\lq", "«", t, flags=re.I)
    t = re.sub(r"\\rq\s*\\rq", "»", t, flags=re.I)
    t = re.sub(r"\\lq\b", "«", t, flags=re.I)
    t = re.sub(r"\\rq\b", "»", t, flags=re.I)
    t = t.replace("{,}", ",")
    t = re.sub(r"\\indam\s*\{", r"\\textbf{", t, flags=re.I)
    t = re.sub(r"\\indam\b", "", t, flags=re.I)
    t = re.sub(r"\\def\\dotEX\{\s*\}", "", t, flags=re.I)
    t = re.sub(r"\\dotEX\b", "", t, flags=re.I)
    t = re.sub(r"\\hoac\b", "hoặc", t, flags=re.I)

    def _plain_outside_math(seg: str) -> str:
        seg = re.sub(r"\\,", " ", seg)
        seg = re.sub(r"\\ldots\b", "…", seg, flags=re.I)
        seg = re.sub(r"\\dots\b", "…", seg, flags=re.I)
        return seg

    if "$" not in t:
        return _plain_outside_math(t)
    parts = t.split("$")
    for i in range(0, len(parts), 2):
        parts[i] = _plain_outside_math(parts[i])
    return "$".join(parts)


def normalize_latex_light(s: Any) -> str:
    """Chuẩn hóa nhẹ — AI hint / lời giải đã đúng: KHÔNG gộp khối $, không sửa câu chữ."""
    t = clean(s)
    if not t:
        return ""
    t = _latex_convert_robot_text_cmds(t)
    orig = t
    t = re.sub(r"\$\$\s*", "$", t)
    t = re.sub(r"\s*\$\$", "$", t)
    t = re.sub(r"\$\s*\n+\s*\$", "", t)
    t = re.sub(r"\$\s*\n+\s*([^$\n]+?)\s*\n+\s*\$", r"$(\1)$", t)
    t = re.sub(r"\$\s*\n+([^$\n]+?)\s*\$", r"$(\1)$", t)
    t = _merge_equiv_chain_math(t)
    t = _merge_adjacent_inline_math(t)
    t = _trim_inline_math_spaces(t)
    if _latex_structure_ok(t):
        return _fix_math_bs_in_pairs(t)
    t = _fix_surplus_dollar_signs(t)
    t = _fix_math_bs_in_pairs(t)
    if not _latex_structure_ok(t) and _latex_structure_ok(orig):
        return _fix_math_bs_in_pairs(orig)
    return t


def normalize_latex_text(s: Any) -> str:
    """Chuẩn hóa LaTeX từ Word/Sheet: ${\\beta}$, \\item, khối $ nuốt tiếng Việt."""
    t = clean(s)
    if not t:
        return ""
    t = _latex_convert_robot_text_cmds(t)
    orig = t
    if _latex_structure_ok(t) and not _latex_needs_heavy_normalize(t):
        return normalize_latex_light(t)
    t = _strip_latex_list_markup(t)
    t = _merge_equiv_chain_math(t)
    t = _merge_broken_dfrac_sqrt(t)
    t = _merge_unit_between_math(t)
    t = _merge_adjacent_inline_math(t)
    t = _fix_surplus_dollar_signs(t)
    t = re.sub(r"\$\{\s*([^}$\n]+?)\s*\}\s*\$", r"$(\1)$", t)
    t = re.sub(r"\$\{\s*([^}$\n]+?)\s*\}", r"$(\1)$", t)
    t = re.sub(r"(?<![$\\])\{\s*\(\s*([^}]+?)\s*\)\s*\}(?![$])", r"$(\1)$", t)
    t = re.sub(r"\$\(\((\\?[a-zA-Z]+)\)\)\$\.?", r"$\\1$.", t)
    t = re.sub(r"\$\(\((\\?[a-zA-Z]+)\)\)(?!\$)", r"$\\1$", t)
    t = _fix_merged_inline_math(t)
    t = _fix_surplus_dollar_signs(t)
    t = re.sub(r"(\$[^$\n]+?\$)\$+", r"\1", t)
    t = re.sub(r"\$\s*\$", " ", t)
    t = _fix_math_bs_in_pairs(t)
    t = _fix_broken_latex_patterns(t)
    if not _latex_structure_ok(t) and _latex_structure_ok(orig):
        return orig
    return _trim_inline_math_spaces(t)


def _fix_broken_latex_patterns(t: str) -> str:
    """Sửa lỗi LaTeX phổ biến từ Word/Sheet (ngoài khối $...$)."""
    if not t:
        return t
    t = re.sub(r"\\acute\{\\mathrm\{i\}\}", "í", t, flags=re.I)
    t = re.sub(
        r"\\text\{\s*([^}]*?)\s*\}\s*\\acute\{[^}]+\}\s*\\text\{\s*t\s*\}",
        r"\\text{\1ít}",
        t,
        flags=re.I,
    )
    t = re.sub(r"(\d+)\s*c\{\{?\s*m\s*\}\}?\^\{3\}", r"$\\1\\,\\text{cm}^{3}$", t, flags=re.I)
    t = re.sub(
        r"\$\(\s*(\d+)\^\{([^{}]+)\}\}(Pa|kPa)\.?\s*\$",
        r"$\1^{\2}\\,\\text{\3}.$",
        t,
        flags=re.I,
    )
    t = re.sub(
        r"\$(\d+)\^\{([^{}]+)\}\}(Pa|kPa)\.?\$",
        r"$\1^{\2}\\,\\text{\3}.$",
        t,
        flags=re.I,
    )
    return t



def _normalize_question_latex_field(field: str, value: Any) -> str:
    v = clean(value)
    if not v:
        return ""
    if field == "DapAn" and not any(x in v for x in ("$", "\\", "{", "}")):
        return v
    if field in ("CauHoi", "A", "B", "C", "D", "LoiGiai", "DapAn", "SaiSo"):
        return normalize_latex_text(v)
    return v


def _normalize_question_latex_updates(
    updates: Dict[str, Any],
    q: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    out = dict(updates or {})
    for f in ("CauHoi", "A", "B", "C", "D", "LoiGiai", "DapAn", "SaiSo"):
        if f in out:
            out[f] = _normalize_question_latex_field(f, out.get(f))
    merged = dict(q or {})
    merged.update({k: clean(v) for k, v in out.items()})
    if "LoiGiai" in out and clean(out.get("LoiGiai")) and effective_dang(merged) == "Đúng sai":
        fixed = normalize_ds_loigiai(out["LoiGiai"], merged)
        if fixed:
            out["LoiGiai"] = fixed
    return out


def stable_hash(text: str, n: int = 12) -> str:
    return hashlib.sha1(text.encode("utf-8", errors="ignore")).hexdigest()[:n].upper()


def now_str() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")


def parse_datetime_any(s: Any) -> Optional[datetime]:
    """Đọc ngày giờ từ Google Sheet: 30/05/2026 13:37, 2026-05-30, hoặc serial dạng text."""
    s = clean(s)
    if not s:
        return None
    # Nếu Google Sheet trả serial ngày dạng số, 1 tương ứng 1899-12-30.
    try:
        if re.fullmatch(r"\d+(?:\.\d+)?", s):
            base = datetime(1899, 12, 30)
            return base + timedelta(days=float(s))
    except Exception:
        pass
    fmts = [
        "%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d",
        "%d/%m/%Y %H:%M:%S", "%d/%m/%Y %H:%M", "%d/%m/%Y",
        "%d-%m-%Y %H:%M:%S", "%d-%m-%Y %H:%M", "%d-%m-%Y",
    ]
    for fmt in fmts:
        try:
            return datetime.strptime(s, fmt)
        except Exception:
            pass
    return None


def fmt_datetime(dt: datetime) -> str:
    return dt.strftime("%d/%m/%Y %H:%M:%S")


def expired_datetime(s: Any) -> bool:
    dt = parse_datetime_any(s)
    return bool(dt and datetime.now() > dt)


def parse_float_vn(s: Any) -> Optional[float]:
    s = clean(s).replace(" ", "")
    if not s:
        return None
    if "," in s and "." not in s:
        s = s.replace(",", ".")
    else:
        s = s.replace(",", "")
    m = re.search(r"[-+]?\d+(?:\.\d+)?", s)
    if not m:
        return None
    try:
        return float(m.group(0))
    except Exception:
        return None


def norm_letter(s: Any) -> str:
    s = clean(s).upper()
    m = re.search(r"[ABCD]", s)
    return m.group(0) if m else ""


def norm_dang(s: Any) -> str:
    t = re.sub(r"[/\\]+", " ", str(s or ""))
    k = key_norm(t)
    k2 = k.replace(" ", "")
    if (
        "dung sai" in k
        or "dungsai" in k2
        or "d/s" in k2
        or re.search(r"\b(ds|tf)\b", k)
        or "true false" in k
        or "truefalse" in k2
    ):
        return "Đúng sai"
    if any(x in k for x in ["tra loi ngan", "short", "tln", "shortans"]):
        return "Trả lời ngắn"
    if any(x in k for x in ["tu luan", "essay"]) or k == "tl":
        return "Tự luận"
    if any(x in k for x in ["trac nghiem", "tracnghiem", "mcq", "multiple choice"]) or k in ("tn", "tn4"):
        return "Trắc nghiệm"
    if k2 in ("ds", "d/s") or k == "ds":
        return "Đúng sai"
    return "Trắc nghiệm"


def bump_count(d: Dict[str, int], key: str) -> None:
    if not key:
        return
    d[key] = int(d.get(key, 0)) + 1


def question_mucdo_parts(q: Dict[str, Any]) -> List[str]:
    lv = clean(q.get("MucDo", "")).upper()
    parts = [p.strip() for p in re.split(r"[,;/|]+", lv) if p.strip()]
    if parts:
        return parts
    return [lv] if lv else []


def infographic_mucdo_label(q: Dict[str, Any]) -> str:
    """Chuẩn hóa mức độ từ cột I để đưa vào prompt infographic."""
    parts = question_mucdo_parts(q)
    if parts:
        return " · ".join(parts)
    return clean(q.get("MucDo", ""))


def infographic_mucdo_highlight_hint(label: str) -> str:
    """Gợi ý màu badge mức độ trên infographic."""
    if not label:
        return "Sheet chưa ghi mức độ (cột I) — vẫn để badge «Mức độ: ?» hoặc bỏ qua."
    u = key_norm(label)
    hints: List[str] = []
    if "nb" in u or "nen tang" in u:
        hints.append("NB → badge xanh lá, chữ TO")
    if re.search(r"\bth\b", u) or "thong hieu" in u:
        hints.append("TH → badge xanh dương")
    if "vdc" in u:
        hints.append("VDC → badge đỏ đậm")
    elif re.search(r"\bvd\b", u) or "van dung" in u:
        hints.append("VD → badge cam")
    if not hints:
        hints.append(f"Badge nổi bật ghi đúng «{label}»")
    return " | ".join(hints)


