def short_plain_text(s: Any, n: int = 160) -> str:
    t = re.sub(r"\s+", " ", clean(s))
    return t if len(t) <= n else t[: max(0, n - 1)] + "…"



# ============================================================
# NHẬP LATEX TRỰC TIẾP VÀO GOOGLE SHEET
# ============================================================

_LATEX_EX_RE = re.compile(r"\\begin\s*\{\s*ex\s*\}([\s\S]*?)\\end\s*\{\s*ex\s*\}", re.I)
_LATEX_INCLUDE_RE = re.compile(r"\\includegraphics(?:\s*\[[^\]]*\])?\s*\{\s*([^{}]+?)\s*\}", re.I)



_LATEX_TIKZ_RE = re.compile(r"\\begin\s*\{\s*tikzpicture\s*\}[\s\S]*?\\end\s*\{\s*tikzpicture\s*\}", re.I)
_LATEX_GRAPHICS_EXTS = (".png", ".jpg", ".jpeg", ".webp", ".gif", ".pdf")


def _safe_asset_name(name: Any) -> str:
    raw = str(name or "").replace("\\", "/").strip().lstrip("/")
    parts = []
    for part in raw.split("/"):
        part = re.sub(r"[^A-Za-z0-9._\- À-ỹĐđ]", "_", part).strip(". ")
        if not part or part in (".", ".."):
            continue
        parts.append(part[:120])
    return "/".join(parts) or ("asset_" + stable_hash(str(name), 10))


def _asset_url_for(batch: str, rel: str) -> str:
    rel = _safe_asset_name(rel)
    return "/static/latex_assets/" + urllib.parse.quote(batch + "/" + rel, safe="/._-%")


def _build_latex_asset_context(commit: bool, assets_zip=None) -> Dict[str, Any]:
    """Chuẩn bị thư mục media cho nhập LaTeX: ảnh includegraphics + TikZ PNG."""
    batch = datetime.now().strftime("%Y%m%d_%H%M%S_") + uuid.uuid4().hex[:8]
    root = os.path.join(LATEX_ASSET_DIR, batch)
    os.makedirs(root, exist_ok=True)
    ctx: Dict[str, Any] = {
        "batch": batch,
        "root": root,
        "map": {},
        "warnings": [],
        "media": {"includegraphics": 0, "tikz": 0, "resolved": 0},
        "commit": bool(commit),
    }
    if assets_zip and getattr(assets_zip, "filename", ""):
        try:
            with tempfile.NamedTemporaryFile(delete=False, suffix=".zip") as tmp:
                assets_zip.save(tmp.name)
                zip_path = tmp.name
            try:
                with zipfile.ZipFile(zip_path) as zf:
                    for info in zf.infolist():
                        if info.is_dir():
                            continue
                        name = _safe_asset_name(info.filename)
                        if not name:
                            continue
                        # Chống zip-slip + bỏ file ẩn hệ thống.
                        if name.startswith("__MACOSX/") or os.path.basename(name).startswith("."):
                            continue
                        dest = os.path.abspath(os.path.join(root, name))
                        if not dest.startswith(os.path.abspath(root) + os.sep):
                            continue
                        os.makedirs(os.path.dirname(dest), exist_ok=True)
                        with zf.open(info) as src, open(dest, "wb") as out:
                            shutil.copyfileobj(src, out)
            finally:
                try:
                    os.unlink(zip_path)
                except Exception:
                    pass
        except Exception as e:
            ctx["warnings"].append({"index": "ZIP", "warning": "Không giải nén được ZIP ảnh: " + str(e)})

    # Lập bản đồ tra cứu theo đường dẫn, basename và tên không đuôi.
    for dirpath, _, files in os.walk(root):
        for fn in files:
            abs_path = os.path.join(dirpath, fn)
            rel = os.path.relpath(abs_path, root).replace("\\", "/")
            rel_key = rel.lower()
            base_key = os.path.basename(rel).lower()
            stem_key = os.path.splitext(base_key)[0].lower()
            url = _asset_url_for(batch, rel)
            for k in {rel_key, base_key, stem_key}:
                ctx["map"].setdefault(k, {"path": abs_path, "url": url, "rel": rel})
    return ctx


def _find_latex_asset(ctx: Optional[Dict[str, Any]], raw_path: str) -> Optional[Dict[str, str]]:
    if not ctx:
        return None
    key = str(raw_path or "").replace("\\", "/").strip().strip("{}").lstrip("./").lower()
    keys = [key, os.path.basename(key)]
    root, ext = os.path.splitext(key)
    if ext:
        keys.append(os.path.basename(root))
    else:
        for e in _LATEX_GRAPHICS_EXTS:
            keys.append(key + e)
            keys.append(os.path.basename(key + e))
    mp = ctx.get("map") or {}
    for k in keys:
        if k in mp:
            return mp[k]
    return None


def _convert_pdf_to_png_if_possible(path: str, ctx: Dict[str, Any], idx: int) -> Optional[str]:
    if not path or not path.lower().endswith(".pdf"):
        return None
    pdftoppm = shutil.which("pdftoppm")
    if not pdftoppm:
        return None
    out_prefix = os.path.join(ctx["root"], f"pdf_q{idx}_{stable_hash(path, 8)}")
    try:
        subprocess.run([pdftoppm, "-png", "-singlefile", "-r", "180", path, out_prefix], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=25)
        out_png = out_prefix + ".png"
        if os.path.exists(out_png):
            rel = os.path.relpath(out_png, ctx["root"]).replace("\\", "/")
            ctx["media"]["resolved"] += 1
            return _asset_url_for(ctx["batch"], rel)
    except Exception as e:
        ctx.setdefault("warnings", []).append({"index": idx, "warning": "Không chuyển PDF hình sang PNG: " + str(e)[:160]})
    return None


def _resolve_includegraphics_path(raw_path: str, ctx: Optional[Dict[str, Any]], idx: int) -> str:
    if ctx:
        ctx["media"]["includegraphics"] += 1
    item = _find_latex_asset(ctx, raw_path)
    if item:
        if item.get("path", "").lower().endswith(".pdf"):
            pdf_png = _convert_pdf_to_png_if_possible(item["path"], ctx, idx) if ctx else None
            if pdf_png:
                return pdf_png
        if ctx:
            ctx["media"]["resolved"] += 1
        return item.get("url") or raw_path
    if ctx:
        ctx.setdefault("warnings", []).append({"index": idx, "warning": f"Không tìm thấy file ảnh includegraphics: {raw_path}. Hãy nén ảnh vào ZIP cùng file .tex."})
    return clean(raw_path)


def _tikz_standalone_document(tikz_code: str) -> str:
    """Gói TikZ vào standalone; tự thêm pgfplots khi có \\begin{axis}."""
    code = clean(tikz_code)
    uses_axis = bool(re.search(r"\\begin\s*\{\s*axis\s*\}", code, re.I)) or "\\addplot" in code
    lines = [
        r"\documentclass[tikz,border=3pt]{standalone}",
        r"\usepackage[utf8]{inputenc}",
        r"\usepackage[T5]{fontenc}",
        r"\usepackage[vietnamese]{babel}",
        r"\usepackage{amsmath,amssymb}",
        r"\usepackage{tikz}",
        r"\usetikzlibrary{arrows.meta,calc,angles,quotes,patterns,decorations.pathmorphing,decorations.markings,intersections,positioning,shapes.geometric}",
    ]
    if uses_axis:
        lines.extend([r"\usepackage{pgfplots}", r"\pgfplotsset{compat=1.18}"])
    lines.extend([r"\begin{document}", code, r"\end{document}", ""])
    return "\n".join(lines)


TIKZ_CACHE_SUBDIR = "_tikz_cache"


def _tikz_normalize_for_cache(tikz_code: str) -> str:
    return re.sub(r"\s+", " ", clean(tikz_code)).strip()


def _tikz_cache_key(tikz_code: str) -> str:
    return stable_hash(_tikz_normalize_for_cache(tikz_code), 16)


def _tikz_cache_dir() -> str:
    d = os.path.join(LATEX_ASSET_DIR, TIKZ_CACHE_SUBDIR)
    os.makedirs(d, exist_ok=True)
    return d


def _tikz_cache_png_path(tikz_code: str) -> str:
    return os.path.join(_tikz_cache_dir(), _tikz_cache_key(tikz_code) + ".png")


def _tikz_cache_png_url(tikz_code: str) -> str:
    path = _tikz_cache_png_path(tikz_code)
    try:
        if os.path.isfile(path) and os.path.getsize(path) > 80:
            key = _tikz_cache_key(tikz_code)
            return "/static/latex_assets/" + TIKZ_CACHE_SUBDIR + "/" + key + ".png"
    except Exception:
        pass
    return ""


def _tikz_promote_to_cache(tikz_code: str, png_path: str) -> str:
    if not tikz_code or not png_path or not os.path.isfile(png_path):
        return ""
    try:
        if os.path.getsize(png_path) < 80:
            return ""
        dest = _tikz_cache_png_path(tikz_code)
        shutil.copy2(png_path, dest)
        return _tikz_cache_png_url(tikz_code)
    except Exception:
        return ""


def _decode_tikzraw_src(src: str) -> str:
    s = clean(src)
    if not s:
        return ""
    if s.lower().startswith("tikzraw:"):
        enc = s[8:].strip()
        pad = "=" * ((4 - len(enc) % 4) % 4)
        try:
            return base64.urlsafe_b64decode(enc + pad).decode("utf-8", errors="replace")
        except Exception:
            return ""
    block = _extract_tikz_block(s)
    return block or s


def _compile_tikz_pdf_via_cloud(tex_doc: str) -> Tuple[bytes, str]:
    """Biên dịch LaTeX → PDF qua latex.ytotech.com (Render không cần cài TeX)."""
    payload = json.dumps({
        "compiler": "pdflatex",
        "resources": [{"main": True, "content": tex_doc}],
    }).encode("utf-8")
    try:
        req = urllib.request.Request(
            "https://latex.ytotech.com/builds/sync",
            data=payload,
            headers={"Content-Type": "application/json", "User-Agent": "LDVL-TikZ/1"},
            method="POST",
        )
        with urllib.request.urlopen(req, timeout=75) as resp:
            data = resp.read()
        if data[:4] == b"%PDF":
            return data, ""
        try:
            err = json.loads(data.decode("utf-8", errors="replace"))
            log = err.get("logs") or err.get("message") or str(err)
            return b"", str(log)[:320]
        except Exception:
            return b"", "Dịch vụ LaTeX trả lỗi không xác định."
    except Exception as e:
        return b"", f"Không gọi được dịch vụ biên dịch LaTeX: {str(e)[:200]}"


def _pdf_bytes_to_png_file(pdf_bytes: bytes, ctx: Dict[str, Any], name: str) -> str:
    """Chuyển PDF → PNG (PyMuPDF hoặc pdftoppm)."""
    if not pdf_bytes or not ctx:
        return ""
    png_path = os.path.join(ctx["root"], name + ".png")
    try:
        import fitz  # pymupdf

        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        if doc.page_count < 1:
            return ""
        page = doc.load_page(0)
        pix = page.get_pixmap(matrix=fitz.Matrix(2.5, 2.5), alpha=False)
        pix.save(png_path)
        ctx["media"]["resolved"] += 1
        drive_url, drive_err = _publish_png_to_drive(png_path, os.path.basename(png_path))
        if drive_url:
            return drive_url
        if drive_err:
            ctx.setdefault("warnings", []).append({"index": name, "warning": drive_err})
        return _asset_url_for(ctx["batch"], os.path.basename(png_path))
    except ImportError:
        pass
    except Exception as e:
        ctx.setdefault("warnings", []).append({"index": name, "warning": "PDF→PNG: " + str(e)[:160]})
        return ""
    pdftoppm = shutil.which("pdftoppm")
    if not pdftoppm:
        return ""
    tmp_pdf = os.path.join(ctx["root"], name + ".pdf")
    out_prefix = os.path.join(ctx["root"], name)
    try:
        with open(tmp_pdf, "wb") as f:
            f.write(pdf_bytes)
        subprocess.run(
            [pdftoppm, "-png", "-singlefile", "-r", "220", tmp_pdf, out_prefix],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=25,
            check=True,
        )
        if os.path.exists(png_path):
            ctx["media"]["resolved"] += 1
            drive_url, drive_err = _publish_png_to_drive(png_path, os.path.basename(png_path))
            if drive_url:
                return drive_url
            if drive_err:
                ctx.setdefault("warnings", []).append({"index": name, "warning": drive_err})
            return _asset_url_for(ctx["batch"], os.path.basename(png_path))
    except Exception as e:
        ctx.setdefault("warnings", []).append({"index": name, "warning": "pdftoppm: " + str(e)[:160]})
    return ""


def _compile_tikz_to_png(tikz_code: str, ctx: Optional[Dict[str, Any]], idx: int, tikz_no: int) -> str:
    tikz_code = clean(tikz_code)
    if not tikz_code:
        return ""
    cached = _tikz_cache_png_url(tikz_code)
    if cached:
        if ctx:
            ctx["media"]["tikz"] += 1
            ctx["media"]["resolved"] += 1
        return cached
    if not ctx:
        return ""
    if ctx:
        ctx["media"]["tikz"] += 1
    tex_doc = _tikz_standalone_document(tikz_code)
    name = f"tikz_{_tikz_cache_key(tikz_code)}"

    def _prefer_cache_url(url: str) -> str:
        if not url:
            return ""
        png_path = os.path.join(ctx["root"], name + ".png")
        cache_url = _tikz_promote_to_cache(tikz_code, png_path)
        return cache_url or url

    pdflatex = shutil.which("pdflatex")
    if pdflatex:
        workdir = os.path.join(ctx["root"], "_tikz_build", name)
        os.makedirs(workdir, exist_ok=True)
        tex_path = os.path.join(workdir, name + ".tex")
        with open(tex_path, "w", encoding="utf-8") as f:
            f.write(tex_doc)
        try:
            subprocess.run(
                [pdflatex, "-interaction=nonstopmode", "-halt-on-error", tex_path],
                cwd=workdir,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=45,
                check=True,
            )
            pdf_path = os.path.join(workdir, name + ".pdf")
            if os.path.exists(pdf_path):
                with open(pdf_path, "rb") as pf:
                    url = _pdf_bytes_to_png_file(pf.read(), ctx, name)
                if url:
                    return _prefer_cache_url(url)
                pdftoppm = shutil.which("pdftoppm")
                if pdftoppm:
                    out_prefix = os.path.join(ctx["root"], name)
                    subprocess.run(
                        [pdftoppm, "-png", "-singlefile", "-r", "220", pdf_path, out_prefix],
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        timeout=25,
                        check=True,
                    )
                    png_path = out_prefix + ".png"
                    if os.path.exists(png_path):
                        ctx["media"]["resolved"] += 1
                        drive_url, drive_err = _publish_png_to_drive(png_path, os.path.basename(png_path))
                        if drive_url:
                            return _prefer_cache_url(drive_url)
                        if drive_err:
                            ctx.setdefault("warnings", []).append({"index": idx, "warning": drive_err})
                        return _prefer_cache_url(_asset_url_for(ctx["batch"], os.path.basename(png_path)))
        except Exception as e:
            ctx.setdefault("warnings", []).append({"index": idx, "warning": "TikZ local: " + str(e)[:180]})

    pdf_bytes, cloud_err = _compile_tikz_pdf_via_cloud(tex_doc)
    if pdf_bytes:
        url = _pdf_bytes_to_png_file(pdf_bytes, ctx, name)
        if url:
            return _prefer_cache_url(url)
    if cloud_err:
        ctx.setdefault("warnings", []).append({"index": idx, "warning": "TikZ cloud: " + cloud_err[:220]})
    return ""


def _latex_extract_media(text: str, ctx: Optional[Dict[str, Any]], idx: int) -> Tuple[str, str]:
    """Gỡ includegraphics/TikZ khỏi câu hỏi, trả về text sạch + link ảnh cột HinhAnh."""
    refs: List[str] = []
    src = text or ""

    def tikz_repl(m: re.Match) -> str:
        url = _compile_tikz_to_png(m.group(0), ctx, idx, len(refs) + 1)
        if url:
            refs.append(url)
        return " "

    src = _LATEX_TIKZ_RE.sub(tikz_repl, src)

    def img_repl(m: re.Match) -> str:
        raw = clean(m.group(1))
        if raw:
            refs.append(_resolve_includegraphics_path(raw, ctx, idx))
        return " "

    # Gỡ cả block center chứa hình, rồi includegraphics lẻ.
    src = re.sub(
        r"\\begin\s*\{\s*center\s*\}\s*" + _LATEX_INCLUDE_RE.pattern + r"\s*\\end\s*\{\s*center\s*\}",
        lambda mm: img_repl(mm),
        src,
        flags=re.I,
    )
    src = _LATEX_INCLUDE_RE.sub(img_repl, src)
    refs = [r for r in refs if clean(r)]
    return src, "; ".join(refs)

def _latex_skip_ws(s: str, pos: int) -> int:
    n = len(s)
    while pos < n and s[pos].isspace():
        pos += 1
    return pos


def _latex_read_braced(s: str, pos: int) -> Tuple[str, int]:
    """Đọc {...} có lồng ngoặc từ vị trí dấu {."""
    pos = _latex_skip_ws(s, pos)
    if pos >= len(s) or s[pos] != "{":
        raise ValueError("Không tìm thấy dấu { trong LaTeX.")
    depth = 0
    out: List[str] = []
    i = pos
    while i < len(s):
        ch = s[i]
        if ch == "\\":
            # Giữ nguyên lệnh và ký tự escape kế tiếp.
            if i + 1 < len(s):
                if depth >= 1:
                    out.append(s[i : i + 2])
                i += 2
                continue
        if ch == "{":
            depth += 1
            if depth >= 2:
                out.append(ch)
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return "".join(out), i + 1
            if depth >= 1:
                out.append(ch)
        else:
            if depth >= 1:
                out.append(ch)
        i += 1
    raise ValueError("Khối {...} LaTeX chưa đóng.")


def _latex_skip_optional_brackets(s: str, pos: int) -> int:
    """Bỏ qua [tuỳ chọn] sau lệnh LaTeX (vd. \\shortans[oly]{...})."""
    while pos < len(s):
        pos = _latex_skip_ws(s, pos)
        if pos >= len(s) or s[pos] != "[":
            break
        depth = 0
        while pos < len(s):
            if s[pos] == "[":
                depth += 1
            elif s[pos] == "]":
                depth -= 1
                if depth == 0:
                    pos += 1
                    break
            pos += 1
    return pos


def _latex_find_command_with_brace(s: str, command: str) -> Optional[Tuple[int, int, str]]:
    m = re.search(r"\\" + re.escape(command) + r"\b", s, re.I)
    if not m:
        return None
    pos = _latex_skip_optional_brackets(s, m.end())
    if pos >= len(s) or s[pos] != "{":
        return None
    val, end = _latex_read_braced(s, pos)
    return m.start(), end, val


def _latex_read_command_args(s: str, command: str, max_args: int = 4) -> Optional[Tuple[int, int, List[str]]]:
    m = re.search(r"\\" + re.escape(command) + r"\b", s, re.I)
    if not m:
        return None
    pos = _latex_skip_optional_brackets(s, m.end())
    args: List[str] = []
    end = pos
    for _ in range(max_args):
        pos = _latex_skip_ws(s, pos)
        if pos >= len(s) or s[pos] != "{":
            break
        val, pos = _latex_read_braced(s, pos)
        args.append(val)
        end = pos
    if not args:
        return None
    return m.start(), end, args


def _latex_strip_comments_keep_meta(s: str) -> str:
    """Bỏ comment đầu dòng nhưng không đụng dấu % trong công thức."""
    lines = []
    for line in str(s or "").splitlines():
        if line.lstrip().startswith("%"):
            continue
        lines.append(line)
    return "\n".join(lines)


def _latex_clean_body(s: Any) -> str:
    t = clean(s)
    if not t:
        return ""
    # Bỏ tag meta kiểu %[Xuất từ robot...] còn sót ngay đầu câu.
    t = re.sub(r"^\s*(?:%\[[^\]]*\]\s*)+", "", t)
    t = re.sub(r"\n{3,}", "\n\n", t)
    t = re.sub(r"[ \t]{2,}", " ", t)
    t = _latex_convert_robot_text_cmds(t.strip())
    return normalize_latex_text(t)


def _latex_extract_images(text: str) -> Tuple[str, str]:
    imgs = [clean(x) for x in _LATEX_INCLUDE_RE.findall(text or "") if clean(x)]
    # Gỡ cả block center chứa hình, sau đó gỡ includegraphics lẻ.
    out = re.sub(
        r"\\begin\s*\{\s*center\s*\}\s*" + _LATEX_INCLUDE_RE.pattern + r"\s*\\end\s*\{\s*center\s*\}",
        " ",
        text or "",
        flags=re.I,
    )
    out = _LATEX_INCLUDE_RE.sub(" ", out)
    return out, "; ".join(imgs)


def _latex_option_clean(opt: str) -> Tuple[str, bool]:
    raw = clean(opt)
    is_true = bool(re.search(r"\\True\b", raw, flags=re.I))
    raw = re.sub(r"\\True\b\s*", "", raw, flags=re.I).strip()
    return _latex_clean_body(raw), is_true


def _latex_meta_id(ex_body: str, idx: int) -> str:
    m = re.search(r"\[Mã\s*câu\s*:\s*([^\]]+)\]", ex_body, re.I)
    if not m:
        m = re.search(r"\[Ma\s*cau\s*:\s*([^\]]+)\]", strip_accents(ex_body), re.I)
    if m:
        return re.sub(r"\s+", "_", clean(m.group(1)))[:80]
    return "LATEX_" + stable_hash(ex_body + str(idx), 12)


_LATEX_EX_TAG_MUCDO_RE = re.compile(r"\[0D1([NHVD])(\d)", re.I)


def _latex_ex_mucdo(raw_block: str, defaults: Optional[Dict[str, Any]] = None) -> str:
    """Đọc mức độ từ tag %[0D1N1-1] trong \\begin{ex} (N→NB, H→TH, V→VD, D→VDC)."""
    defaults = defaults or {}
    preset = clean(defaults.get("MucDo", "")).upper()
    if preset in ("NB", "TH", "VD", "VDC"):
        return preset
    m = _LATEX_EX_TAG_MUCDO_RE.search(str(raw_block or ""))
    if not m:
        return ""
    return {"N": "NB", "H": "TH", "V": "VD", "D": "VDC"}.get(m.group(1).upper(), "")


_LATEX_DANGBT_RE = re.compile(r"\\dangbt\s*\{([^{}]+)\}", re.I)
_LATEX_CHAPTER_RE = re.compile(r"\\chapter\*?\s*(?:\[[^\]]*\])?\s*\{([^{}]+)\}", re.I)
_LATEX_SECTION_RE = re.compile(r"\\section\*?\s*(?:\[[^\]]*\])?\s*\{([^{}]+)\}", re.I)
_LATEX_SUBSECTION_RE = re.compile(r"\\subsection\*?\s*(?:\[[^\]]*\])?\s*\{([^{}]+)\}", re.I)
_LATEX_SUBSUBSECTION_RE = re.compile(r"\\subsubsection\*?\s*(?:\[[^\]]*\])?\s*\{([^{}]+)\}", re.I)
_LATEX_THEORY_STOP_RE = re.compile(
    r"\\begin\s*\{\s*(?:ex|bt|caulc)\s*\}|\\dangbt\s*\{|\\caulc\b",
    re.I,
)
_LATEX_THEORY_ENV_NAMES = r"dn|note|vidu|vd|kttrongtam|dinhnghia|node"
_LATEX_THEORY_ENV_BEGIN_RE = re.compile(
    rf"\\begin\s*\{{\s*({_LATEX_THEORY_ENV_NAMES})\s*\}}",
    re.I,
)
_LATEX_THEORY_ENV_RE = re.compile(
    rf"\\begin\s*\{{\s*({_LATEX_THEORY_ENV_NAMES})\s*\}}(?:\s*\[([^\]]*)\])?([\s\S]*?)"
    rf"\\end\s*\{{\s*\1\s*\}}",
    re.I,
)


def _latex_theory_env_canonical(name: str) -> str:
    n = clean(name).lower()
    if n in ("kttrongtam", "dinhnghia", "dn"):
        return "dn"
    if n in ("node", "note"):
        return "note"
    if n in ("vd", "vidu"):
        return "vidu"
    return n


def _latex_fold_loigiai_in_content(content: str) -> str:
    out = str(content or "")
    while True:
        cmd = _latex_find_command_with_brace(out, "loigiai")
        if not cmd:
            break
        start, end, inner = cmd
        repl = "\n\n\\textbf{Lời giải:}\n" + clean(inner)
        out = out[:start] + repl + out[end:]
    return out


def _latex_read_optional_bracket_title(s: str, pos: int) -> Tuple[str, int]:
    pos = _latex_skip_ws(s, pos)
    if pos >= len(s) or s[pos] != "[":
        return "", pos
    depth = 0
    i = pos
    while i < len(s):
        if s[i] == "[":
            depth += 1
        elif s[i] == "]":
            depth -= 1
            if depth == 0:
                return s[pos + 1 : i], i + 1
        i += 1
    return "", pos


def _latex_split_theory_piece(segment: str) -> List[Tuple[str, str, str]]:
    """Trả về (env_chuẩn, tiêu đề_tuỳ_chọn, nội_dung) từ đoạn lý thuyết sách."""
    segment = str(segment or "")
    results: List[Tuple[str, str, str]] = []
    pos = 0
    pending_title = ""
    n = len(segment)
    while pos < n:
        pos = _latex_skip_ws(segment, pos)
        if pos >= n:
            break
        hm = _LATEX_SUBSUBSECTION_RE.match(segment, pos)
        if hm:
            pending_title = clean(hm.group(1))
            pos = hm.end()
            continue
        sm = _LATEX_SUBSECTION_RE.match(segment, pos)
        if sm:
            pos = sm.end()
            continue
        em = _LATEX_THEORY_ENV_BEGIN_RE.match(segment, pos)
        if not em:
            pos += 1
            continue
        env_raw = em.group(1)
        p = em.end()
        optional_bracket, p = _latex_read_optional_bracket_title(segment, p)
        p = _latex_skip_ws(segment, p)
        if p >= n or segment[p] != "{":
            pos += 1
            continue
        try:
            content, end = _latex_read_braced(segment, p)
        except ValueError:
            pos += 1
            continue
        end_env = re.match(
            rf"\\end\s*\{{\s*{re.escape(env_raw)}\s*\}}",
            segment[end:],
            re.I,
        )
        if not end_env:
            pos += 1
            continue
        block_end = end + end_env.end()
        content = _latex_fold_loigiai_in_content(content)
        canon = _latex_theory_env_canonical(env_raw)
        opt = optional_bracket or (pending_title if canon == "dn" else "")
        if pending_title and canon != "dn":
            opt = opt or pending_title
        pending_title = ""
        results.append((canon, clean(opt), content))
        pos = block_end
    return results


def _latex_theory_blocks_to_source(pieces: List[Tuple[str, str, str]]) -> str:
    block_strs: List[str] = []
    for canon, opt, content in pieces:
        body = clean(content)
        if not body and not opt:
            continue
        opt_s = f"[{opt}]" if opt else ""
        block_strs.append(f"\\begin{{{canon}}}{opt_s}\n{body}\n\\end{{{canon}}}")
    return normalize_method_latex_source("\n\n".join(block_strs))


def _latex_theory_item_from_pieces(
    pieces: List[Tuple[str, str, str]],
    defaults: Dict[str, Any],
    *,
    chuong: str,
    baihoc: str,
    tieude: str,
) -> Optional[Dict[str, Any]]:
    source = _latex_theory_blocks_to_source(pieces)
    if not source:
        return None
    item = {f: "" for f in LEARNING_THEORY_FIELDS}
    item.update({
        "Mon": clean(defaults.get("Mon", "")),
        "Lop": clean(defaults.get("Lop", "")),
        "Chuong": chuong or clean(defaults.get("Chuong", "")),
        "BaiHoc": baihoc or clean(defaults.get("BaiHoc", "")),
        "TieuDe": tieude or baihoc or clean(defaults.get("BaiHoc", "")) or "Lý thuyết",
        "TrangThai": "OK",
        "NgayCapNhat": datetime.now().strftime("%d/%m/%Y %H:%M"),
        "NoiDungLaTeX": source,
    })
    item["ID"] = "LT_" + stable_hash(
        "|".join(item.get(k, "") for k in ["Mon", "Lop", "Chuong", "BaiHoc"]),
        12,
    )
    return item


def parse_latex_lesson_theory_2026(tex: str, defaults: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    """Đọc lý thuyết sách: \\chapter, \\section, kttrongtam/note/vd → sheet Ly_Thuyet."""
    defaults = defaults or {}
    raw = str(tex or "").replace("\r\n", "\n").replace("\r", "\n")
    ch_m = _LATEX_CHAPTER_RE.search(raw)
    chapter_default = clean(ch_m.group(1)) if ch_m else clean(defaults.get("Chuong", ""))
    items: List[Dict[str, Any]] = []
    parts = re.split(r"(?=\\section\*?\s*(?:\[[^\]]*\])?\s*\{)", raw, flags=re.I)
    for part in parts:
        sm = _LATEX_SECTION_RE.search(part)
        if not sm:
            continue
        section_title = clean(sm.group(1))
        body = part[sm.end() :]
        stop = _LATEX_THEORY_STOP_RE.search(body)
        theory_seg = body[: stop.start()] if stop else body
        pieces = _latex_split_theory_piece(theory_seg)
        item = _latex_theory_item_from_pieces(
            pieces,
            defaults,
            chuong=chapter_default,
            baihoc=section_title,
            tieude=section_title,
        )
        if item:
            items.append(item)
    if not items and _LATEX_THEORY_ENV_BEGIN_RE.search(raw):
        pieces = _latex_split_theory_piece(raw)
        item = _latex_theory_item_from_pieces(
            pieces,
            defaults,
            chuong=chapter_default,
            baihoc=clean(defaults.get("BaiHoc", "")) or "Lý thuyết",
            tieude=clean(defaults.get("BaiHoc", "")) or chapter_default or "Lý thuyết",
        )
        if item:
            items.append(item)
    return items


def _latex_dangbt_markers(tex: str) -> List[Tuple[int, int, str]]:
    return [(m.start(), m.end(), clean(m.group(1))) for m in _LATEX_DANGBT_RE.finditer(str(tex or ""))]


def _latex_dangbt_at(markers: List[Tuple[int, int, str]], pos: int) -> str:
    value = ""
    for start, _end, title in markers:
        if start > pos:
            break
        value = title
    return value


def parse_latex_theory_groups_2026(tex: str, defaults: Optional[Dict[str, Any]] = None) -> List[Dict[str, Any]]:
    """Tách khung dn/note/vidu theo từng \\dangbt để lưu sheet Phuong_Phap."""
    defaults = defaults or {}
    raw = str(tex or "").replace("\r\n", "\n").replace("\r", "\n")
    markers = _latex_dangbt_markers(raw)
    items: List[Dict[str, Any]] = []
    for idx, (start, end, title) in enumerate(markers):
        seg_end = markers[idx + 1][0] if idx + 1 < len(markers) else len(raw)
        segment = normalize_method_latex_source(raw[end:seg_end])
        blocks: List[str] = []
        for m in _LATEX_THEORY_ENV_RE.finditer(segment):
            env = _latex_theory_env_canonical(m.group(1))
            optional_title = clean(m.group(2))
            content = _latex_fold_loigiai_in_content(m.group(3))
            if not content:
                continue
            opt = f"[{optional_title}]" if optional_title else ""
            blocks.append(f"\\begin{{{env}}}{opt}\n{content}\n\\end{{{env}}}")
        if not blocks or not title:
            continue
        source = normalize_method_latex_source("\n\n".join(blocks))
        item = {f: "" for f in LEARNING_METHOD_FIELDS}
        item.update({
            "Mon": clean(defaults.get("Mon", "")),
            "Lop": clean(defaults.get("Lop", "")),
            "Chuong": clean(defaults.get("Chuong", "")),
            "BaiHoc": clean(defaults.get("BaiHoc", "")),
            "DangBaiTap": title,
            "TenPhuongPhap": title,
            "TrangThai": "OK",
            "NgayCapNhat": datetime.now().strftime("%d/%m/%Y %H:%M"),
            "NoiDungLaTeX": source,
        })
        item["ID"] = "PP_" + stable_hash("|".join(item.get(k, "") for k in ["Mon", "Lop", "Chuong", "BaiHoc", "DangBaiTap"]), 12)
        items.append(item)
    return items


def parse_latex_questions_2026(tex: str, defaults: Optional[Dict[str, Any]] = None, asset_ctx: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Parse file .tex dạng \\begin{ex} ... \\choice/\\choiceTF/\\shortans/\\loigiai."""
    defaults = defaults or {}
    tex = str(tex or "").replace("\r\n", "\n").replace("\r", "\n")
    blocks = list(_LATEX_EX_RE.finditer(tex))
    dangbt_markers = _latex_dangbt_markers(tex)
    out: List[Dict[str, Any]] = []
    errors: List[Dict[str, Any]] = []

    for idx, m in enumerate(blocks, start=1):
        raw_block = m.group(1)
        try:
            work = raw_block

            lg = ""
            lg_cmd = _latex_find_command_with_brace(work, "loigiai")
            if lg_cmd:
                work = work[: lg_cmd[0]] + "\n" + work[lg_cmd[1] :]
                lg = _latex_clean_body(lg_cmd[2])

            # Ưu tiên Trả lời ngắn, rồi Đúng/Sai, rồi Trắc nghiệm.
            short_cmd = _latex_find_command_with_brace(work, "shortans")
            tf_cmd = _latex_read_command_args(work, "choiceTF", 4)
            choice_cmd = _latex_read_command_args(work, "choice", 4)

            q: Dict[str, Any] = {f: clean(defaults.get(f, "")) for f in QUESTION_FIELDS}
            marker_dbt = _latex_dangbt_at(dangbt_markers, m.start())
            if marker_dbt:
                q["DangBaiTap"] = marker_dbt
            q["ID"] = clean(defaults.get("ID", "")) or _latex_meta_id(raw_block, idx)
            tag_mucdo = _latex_ex_mucdo(raw_block, defaults)
            if tag_mucdo:
                q["MucDo"] = tag_mucdo
            if not q.get("QuyenTruyCap"):
                q["QuyenTruyCap"] = "VIP"
            if not q.get("Diem"):
                q["Diem"] = "1"
            q["LoiGiai"] = lg

            if short_cmd:
                q_text = work[: short_cmd[0]]
                q_text, imgs = _latex_extract_media(q_text, asset_ctx, idx)
                q["CauHoi"] = _latex_clean_body(_latex_strip_comments_keep_meta(q_text))
                q["Dang"] = "Trả lời ngắn"
                q["DangBaiTap"] = q.get("DangBaiTap", "")
                q["DapAn"] = _latex_clean_body(short_cmd[2])
                q["A"] = q["B"] = q["C"] = q["D"] = ""
                if imgs and not q.get("HinhAnh"):
                    q["HinhAnh"] = imgs

            elif tf_cmd:
                q_text = work[: tf_cmd[0]]
                q_text, imgs = _latex_extract_media(q_text, asset_ctx, idx)
                q["CauHoi"] = _latex_clean_body(_latex_strip_comments_keep_meta(q_text))
                q["Dang"] = "Đúng sai"
                vals = []
                for L, opt in zip(["A", "B", "C", "D"], tf_cmd[2]):
                    body, is_true = _latex_option_clean(opt)
                    q[L] = body
                    vals.append("Đ" if is_true else "S")
                while len(vals) < 4:
                    vals.append("")
                q["DapAn"] = ",".join(v for v in vals[:4] if v)
                if imgs and not q.get("HinhAnh"):
                    q["HinhAnh"] = imgs

            elif choice_cmd:
                q_text = work[: choice_cmd[0]]
                q_text, imgs = _latex_extract_media(q_text, asset_ctx, idx)
                q["CauHoi"] = _latex_clean_body(_latex_strip_comments_keep_meta(q_text))
                q["Dang"] = "Trắc nghiệm"
                true_letter = ""
                for L, opt in zip(["A", "B", "C", "D"], choice_cmd[2]):
                    body, is_true = _latex_option_clean(opt)
                    q[L] = body
                    if is_true and not true_letter:
                        true_letter = L
                q["DapAn"] = true_letter
                if imgs and not q.get("HinhAnh"):
                    q["HinhAnh"] = imgs

            else:
                # Không có lệnh đáp án: vẫn nhập như tự luận để ADMIN sửa tiếp.
                q_text, imgs = _latex_extract_media(work, asset_ctx, idx)
                q["CauHoi"] = _latex_clean_body(_latex_strip_comments_keep_meta(q_text))
                q["Dang"] = "Tự luận"
                if imgs and not q.get("HinhAnh"):
                    q["HinhAnh"] = imgs

            q["Dang"] = effective_dang(q)
            if q["Dang"] == "Trắc nghiệm" and not is_mcq_letter_answer(q.get("DapAn")):
                errors.append({"index": idx, "id": q.get("ID", ""), "warning": "Trắc nghiệm chưa tìm thấy \\True."})
            if q["Dang"] == "Đúng sai" and not looks_like_dungsai_answer(q.get("DapAn")):
                errors.append({"index": idx, "id": q.get("ID", ""), "warning": "Đúng/Sai chưa đủ đáp án Đ/S."})

            if clean(q.get("CauHoi")):
                out.append(q)
            else:
                errors.append({"index": idx, "id": q.get("ID", ""), "warning": "Không đọc được nội dung câu hỏi."})

        except Exception as e:
            errors.append({"index": idx, "warning": str(e)})

    counts = {"Trắc nghiệm": 0, "Đúng sai": 0, "Trả lời ngắn": 0, "Tự luận": 0}
    for q in out:
        counts[effective_dang(q)] = counts.get(effective_dang(q), 0) + 1

    if asset_ctx:
        errors.extend(asset_ctx.get("warnings", []))

    return {
        "ok": True,
        "total_blocks": len(blocks),
        "parsed": len(out),
        "counts": counts,
        "questions": out,
        "warnings": errors,
        "media": (asset_ctx.get("media") if asset_ctx else {"includegraphics": 0, "tikz": 0, "resolved": 0}),
    }

def short_plain_text(s: Any, n: int = 160) -> str:
    t = re.sub(r"\s+", " ", clean(s))
    return t if len(t) <= n else t[: max(0, n - 1)] + "…"




# ============================================================
# ADMIN GPT: NHẬN DIỆN MỨC ĐỘ NB/TH/VD/VDC KHI NHẬP LATEX
# ============================================================

def _norm_mucdo_4(value: Any) -> str:
    raw = clean(value).upper()
    if raw in ("NB", "TH", "VD", "VDC"):
        return raw
    k = key_norm(value)
    if "van dung cao" in k or "vdc" in k:
        return "VDC"
    if "van dung" in k or re.search(r"\bvd\b", k):
        return "VD"
    if "thong hieu" in k or re.search(r"\bth\b", k):
        return "TH"
    if "nhan biet" in k or re.search(r"\bnb\b", k):
        return "NB"
    return ""


def _latex_ai_level_requested(defaults: Dict[str, Any], explicit: Any = None) -> bool:
    if isinstance(explicit, bool):
        return explicit
    if clean(explicit).lower() in ("1", "true", "yes", "on", "ai"):
        return True
    raw = clean((defaults or {}).get("MucDo", ""))
    k = key_norm(raw).replace(" ", "")
    return raw.upper() in ("AI", "AUTO", "GPT") or "tudong" in k or ("ai" in k and "nhan" in k)


def _apply_latex_level_overrides(questions: List[Dict[str, Any]], overrides: Any) -> int:
    if isinstance(overrides, str):
        try:
            overrides = json.loads(overrides or "[]")
        except Exception:
            overrides = []
    if not isinstance(overrides, list):
        return 0
    mp: Dict[int, str] = {}
    for it in overrides:
        if not isinstance(it, dict):
            continue
        try:
            idx = int(it.get("index") or it.get("idx") or 0)
        except Exception:
            idx = 0
        lv = _norm_mucdo_4(it.get("MucDo") or it.get("mucdo") or it.get("level"))
        if idx > 0 and lv:
            mp[idx] = lv
    n = 0
    for i, q in enumerate(questions or [], start=1):
        if i in mp:
            q["MucDo"] = mp[i]
            n += 1
    return n


def _latex_level_prompt_items(questions: List[Dict[str, Any]], start_index: int) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for off, q in enumerate(questions, start=0):
        items.append({
            "index": start_index + off,
            "Mon": clean(q.get("Mon", "")),
            "Lop": clean(q.get("Lop", "")),
            "Chuong": clean(q.get("Chuong", "")),
            "BaiHoc": clean(q.get("BaiHoc", "")),
            "DangBaiTap": clean(q.get("DangBaiTap", "")),
            "Dang": clean(q.get("Dang", "")),
            "CauHoi": clean(q.get("CauHoi", ""))[:1800],
            "A": clean(q.get("A", ""))[:500],
            "B": clean(q.get("B", ""))[:500],
            "C": clean(q.get("C", ""))[:500],
            "D": clean(q.get("D", ""))[:500],
            "DapAn": clean(q.get("DapAn", ""))[:300],
            "LoiGiai": clean(q.get("LoiGiai", ""))[:1200],
        })
    return items


def admin_gpt_classify_latex_levels(
    questions: List[Dict[str, Any]],
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
) -> Dict[str, Any]:
    """ADMIN: gợi ý MucDo NB/TH/VD/VDC — Gemini trước."""
    meta: Dict[str, Any] = {
        "ai_level": True,
        "ai_level_done": False,
        "ai_model": "",
        "ai_provider": "GEMINI",
        "ai_level_error": "",
        "warnings": [],
    }
    if not questions:
        return meta

    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI")
    gemini_keys = load_ai_keys("GEMINI")
    if not openai_keys and not gemini_keys:
        meta["ai_level_error"] = "Chưa có key AI (Gemini/GPT) cho ADMIN."
        for q in questions:
            q["_AiMucDo"] = ""
            q["_AiConfidence"] = ""
            q["_AiReason"] = meta["ai_level_error"]
            q["MucDo"] = _norm_mucdo_4(q.get("MucDo")) or ""
        return meta

    sys_prompt = (
        "Bạn là giáo viên THPT Việt Nam, chuyên phân loại mức độ câu hỏi. "
        "Chỉ trả JSON hợp lệ, không markdown, không giải thích ngoài JSON."
    )
    rules = """
Phân loại đúng 4 mức:
NB = Nhận biết: hỏi định nghĩa, khái niệm, đơn vị, công thức trực tiếp, chỉ nhớ là trả lời được.
TH = Thông hiểu: hiểu bản chất, nhận xét/giải thích/suy luận 1 bước, chưa cần tính toán phức tạp.
VD = Vận dụng: dùng công thức, thay số, đổi đơn vị, tính toán 2-3 bước hoặc kết hợp vài dữ kiện.
VDC = Vận dụng cao: nhiều bước, bẫy, đồ thị, cực trị, biến đổi phức tạp, phối hợp nhiều kiến thức.

Nếu có DangBaiTap (dạng bài tập cột H) thì dùng làm ngữ cảnh phân loại mức độ, không đổi tên dạng bài tập.

Yêu cầu JSON:
{"items":[{"index":1,"MucDo":"NB","confidence":0.90,"reason":"Hỏi khái niệm trực tiếp."}]}
MucDo chỉ được là NB, TH, VD, VDC. reason tối đa 18 từ.
""".strip()

    total_ok = 0
    chunk_size = 25
    for start in range(0, len(questions), chunk_size):
        chunk = questions[start : start + chunk_size]
        items = _latex_level_prompt_items(chunk, start + 1)
        user_prompt = rules + "\n\nDANH SÁCH CÂU:\n" + json.dumps(items, ensure_ascii=False)
        last_err = ""
        obj: Dict[str, Any] = {}
        try:
            txt, prov, model, _ki = admin_ai_call_text(
                sys_prompt,
                user_prompt,
                max_tokens=2200,
                temp=0.02,
                timeout=55,
                force_provider=force_provider,
                allow_gpt_fallback=allow_gpt_fallback,
            )
            meta["ai_provider"] = prov
            meta["ai_model"] = model
            obj = _extract_ai_json_object(txt)
            if not isinstance(obj.get("items"), list):
                last_err = "AI trả JSON không đúng schema."
                obj = {}
        except AdminGeminiQuotaError:
            raise
        except Exception as e:
            last_err = clean(str(e))
            obj = {}
        ai_items = obj.get("items") if isinstance(obj, dict) else None
        if not isinstance(ai_items, list):
            msg = f"AI ADMIN chưa phân mức được câu {start+1}-{start+len(chunk)}: {last_err or 'không có phản hồi'}"
            meta["warnings"].append(msg)
            for q in chunk:
                q["_AiMucDo"] = ""
                q["_AiConfidence"] = ""
                q["_AiReason"] = msg
                q["MucDo"] = _norm_mucdo_4(q.get("MucDo")) or ""
            continue

        by_index: Dict[int, Dict[str, Any]] = {}
        for it in ai_items:
            if not isinstance(it, dict):
                continue
            try:
                idx = int(it.get("index") or 0)
            except Exception:
                idx = 0
            lv = _norm_mucdo_4(it.get("MucDo") or it.get("level"))
            if idx and lv:
                by_index[idx] = it

        for off, q in enumerate(chunk, start=0):
            idx = start + off + 1
            it = by_index.get(idx)
            if not it:
                q["_AiMucDo"] = ""
                q["_AiConfidence"] = ""
                q["_AiReason"] = "GPT chưa trả mức cho câu này."
                q["MucDo"] = _norm_mucdo_4(q.get("MucDo")) or ""
                continue
            lv = _norm_mucdo_4(it.get("MucDo") or it.get("level"))
            q["MucDo"] = lv
            q["_AiMucDo"] = lv
            conf = it.get("confidence", "")
            try:
                conf = f"{float(conf):.2f}"
            except Exception:
                conf = clean(conf)
            q["_AiConfidence"] = clean(conf)
            q["_AiReason"] = clean(it.get("reason") or it.get("ly_do") or "")[:180]
            total_ok += 1

    meta["ai_level_done"] = total_ok > 0
    if total_ok < len(questions):
        meta["ai_level_error"] = f"AI phân được {total_ok}/{len(questions)} câu."
    return meta


def _dangbaitap_bulk_prompt_items(
    questions: List[Dict[str, Any]],
    start_index: int,
    store: "SheetStore",
    meta_sug: List[str],
    lesson_types_assigned: Optional[Dict[str, List[str]]] = None,
) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    lesson_types_assigned = lesson_types_assigned or {}
    for off, q in enumerate(questions, start=0):
        scoped, scope_level = _scoped_dangbaitap_suggestions(store, q, limit=DBT_MAX_TYPES_PER_LESSON)
        suggestions = _merge_dangbaitap_suggestions(
            list(lesson_types_assigned.get(_lesson_scope_key(q)) or [])[:DBT_MAX_TYPES_PER_LESSON],
            scoped,
            meta_sug,
            limit=DBT_MAX_TYPES_PER_LESSON,
        )
        opts = {L: clean(q.get(L, ""))[:400] for L in "ABCD" if clean(q.get(L, ""))}
        items.append({
            "index": start_index + off,
            "Mon": clean(q.get("Mon", "")),
            "Lop": clean(q.get("Lop", "")),
            "Chuong": clean(q.get("Chuong", "")),
            "BaiHoc": clean(q.get("BaiHoc", "")),
            "Dang": clean(q.get("Dang", "")),
            "MucDo": clean(q.get("MucDo", "")),
            "DangBaiTap_current": clean(q.get("DangBaiTap", "")),
            "scope_level": scope_level,
            "dbt_existing": suggestions,
            "lesson_dbt_cap": DBT_MAX_TYPES_PER_LESSON,
            "lesson_dbt_already_used": list(lesson_types_assigned.get(_lesson_scope_key(q)) or [])[:DBT_MAX_TYPES_PER_LESSON],
            "CauHoi": clean(q.get("CauHoi", ""))[:1500],
            "options": opts,
        })
    return items


def admin_gpt_classify_dangbaitap_bulk(
    questions: List[Dict[str, Any]],
    store: "SheetStore",
    lesson_dbt_context: Optional[Dict[str, List[str]]] = None,
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
) -> Dict[str, Any]:
    """ADMIN: gợi ý DangBaiTap (cột H) — Gemini trước."""
    meta: Dict[str, Any] = {
        "ai_dbt": True,
        "ai_dbt_done": False,
        "ai_model": "",
        "ai_provider": "GEMINI",
        "ai_dbt_error": "",
        "warnings": [],
    }
    if not questions:
        return meta

    cfg = ai_runtime_config()
    openai_keys = load_ai_keys("OPENAI")
    gemini_keys = load_ai_keys("GEMINI")
    model = clean(cfg.get("openai_admin_model") or DEFAULT_OPENAI_ADMIN_MODEL) or DEFAULT_OPENAI_ADMIN_MODEL
    meta_sug: List[str] = []
    try:
        meta_sug = ((store.meta() or {}).get("filters") or {}).get("DangBaiTap") or []
    except Exception:
        meta_sug = []

    if not openai_keys and not gemini_keys:
        meta["ai_dbt_error"] = "Chưa có key AI (Gemini/GPT) cho ADMIN."
        for q in questions:
            q["_AiDangBaiTap"] = ""
            q["_AiReason"] = meta["ai_dbt_error"]
            q["_AiMatchedExisting"] = False
        return meta

    sys_prompt = (
        "Bạn là giáo viên THPT Việt Nam, chuyên phân loại Dạng bài tập (cột H). "
        "Chỉ trả JSON hợp lệ, không markdown, không giải thích ngoài JSON."
    )
    rules = f"""
Nhiệm vụ: đặt tên DẠNG BÀI TẬP (DangBaiTap) cho từng câu — KHÔNG phải dạng câu TN/ĐS/TLN.

Quy tắc:
- Mỗi câu có dbt_existing: nếu khớp → trả ĐÚNG NGUYÊN VĂN tên trong danh sách (used_existing=true).
- Tên mới: 4-12 từ, cụ thể, dùng cho nhiều câu cùng phương pháp (used_existing=false).
- Trong CÙNG một Bài học (Mon+Chuong+BaiHoc): tối đa {DBT_MAX_TYPES_PER_LESSON} tên dạng KHÁC NHAU cho cả bài.
- Ưu tiên tái dùng dbt_existing và lesson_dbt_already_used — gom câu cùng phương pháp, không tách quá chi tiết.
- Nếu lesson_dbt_already_used đã có {DBT_MAX_TYPES_PER_LESSON} dạng → BẮT BUỘC gán câu mới vào một trong các dạng đó.
- Không trả 'Trắc nghiệm', 'Đúng sai', 'Trả lời ngắn', 'Tự luận'.
- Không nêu đáp án/kết quả cuối.

JSON:
{{"items":[{{"index":1,"DangBaiTap":"tên dạng","reason":"lý do ngắn","used_existing":true}}]}}
reason tối đa 20 từ.
""".strip()

    lesson_types_assigned: Dict[str, List[str]] = {}
    if lesson_dbt_context:
        for sk, names in lesson_dbt_context.items():
            if not isinstance(names, list):
                continue
            lesson_types_assigned[str(sk)] = [
                clean(x) for x in names if clean(x) and not _is_bad_dangbaitap_value(x)
            ][:DBT_MAX_TYPES_PER_LESSON]

    total_ok = 0
    chunk_size = 6
    for start in range(0, len(questions), chunk_size):
        chunk = questions[start : start + chunk_size]
        items = _dangbaitap_bulk_prompt_items(chunk, start + 1, store, meta_sug, lesson_types_assigned)
        sug_by_idx: Dict[int, List[str]] = {}
        for it in items:
            try:
                idx = int(it.get("index") or 0)
            except Exception:
                idx = 0
            if idx:
                sug_by_idx[idx] = list(it.get("dbt_existing") or [])
        user_prompt = rules + "\n\nDANH SÁCH CÂU:\n" + json.dumps(items, ensure_ascii=False)
        last_err = ""
        obj: Dict[str, Any] = {}
        try:
            txt, prov, model_used, _ki = admin_ai_call_text(
                sys_prompt,
                user_prompt,
                max_tokens=2800,
                temp=0.02,
                timeout=45,
                force_provider=force_provider,
                allow_gpt_fallback=allow_gpt_fallback,
            )
            meta["ai_provider"] = prov
            meta["ai_model"] = model_used
            obj = _extract_ai_json_object(txt)
            if not isinstance(obj.get("items"), list):
                last_err = "AI trả JSON không đúng schema."
                obj = {}
        except AdminGeminiQuotaError:
            raise
        except Exception as e:
            last_err = clean(str(e))
            obj = {}
        ai_items = obj.get("items") if isinstance(obj, dict) else None
        if not isinstance(ai_items, list):
            msg = f"AI ADMIN chưa gợi ý Dạng BT câu {start+1}-{start+len(chunk)}: {last_err or 'không có phản hồi'}"
            meta["warnings"].append(msg)
            for q in chunk:
                q["_AiDangBaiTap"] = ""
                q["_AiReason"] = msg
                q["_AiMatchedExisting"] = False
            continue

        by_index: Dict[int, Dict[str, Any]] = {}
        for it in ai_items:
            if not isinstance(it, dict):
                continue
            try:
                idx = int(it.get("index") or 0)
            except Exception:
                idx = 0
            ai_raw = clean(it.get("DangBaiTap") or it.get("dangbaitap") or "")
            if idx and ai_raw and not _is_bad_dangbaitap_value(ai_raw):
                by_index[idx] = it

        for off, q in enumerate(chunk, start=0):
            idx = start + off + 1
            it = by_index.get(idx)
            if not it:
                q["_AiDangBaiTap"] = ""
                q["_AiReason"] = "GPT chưa trả Dạng bài tập cho câu này."
                q["_AiMatchedExisting"] = False
                continue
            ai_raw = clean(it.get("DangBaiTap") or it.get("dangbaitap") or "")
            suggestions = _merge_dangbaitap_suggestions(sug_by_idx.get(idx, []), meta_sug, limit=50)
            val, synced_from, matched_existing = _resolve_dangbaitap_to_suggestions(ai_raw, suggestions)
            if not val:
                q["_AiDangBaiTap"] = ""
                q["_AiReason"] = "GPT trả Dạng bài tập không hợp lệ."
                q["_AiMatchedExisting"] = False
                continue
            q["_AiDangBaiTap"] = val
            q["_AiReason"] = clean(it.get("reason") or "")[:180]
            q["_AiMatchedExisting"] = bool(matched_existing)
            if synced_from and synced_from != ai_raw:
                q["_AiReason"] = (q["_AiReason"] + f" (đồng bộ «{synced_from}»)").strip()[:180]
            sk = _lesson_scope_key(q)
            lst = lesson_types_assigned.setdefault(sk, [])
            kn_val = key_norm(val)
            if not any(key_norm(x) == kn_val for x in lst):
                lst.append(val)
            if len(lst) > DBT_MAX_TYPES_PER_LESSON:
                lst[:] = lst[:DBT_MAX_TYPES_PER_LESSON]
            total_ok += 1

    cons = _consolidate_dangbaitap_per_lesson(questions, DBT_MAX_TYPES_PER_LESSON)
    if cons.get("merged"):
        meta["warnings"].append(
            f"Đã gộp {cons['merged']} câu về tối đa {DBT_MAX_TYPES_PER_LESSON} dạng/bài cho gọn."
        )
    meta["dbt_lesson_consolidation"] = cons

    meta["ai_dbt_done"] = total_ok > 0
    if total_ok < len(questions):
        meta["ai_dbt_error"] = f"GPT gợi ý được {total_ok}/{len(questions)} câu."
    return meta


def _sanitize_assistant_note_text(txt: Any) -> str:
    """Chuẩn hóa LaTeX/ký tự; giữ đáp án cuối (TN/Đ/S/TLN)."""
    t = sanitize_hint_math_text(clean(txt))
    if not t:
        return ""
    if len(t) > 2400:
        t = t[:2400].rstrip() + "…"
    return t


def _strip_student_final_answer_text(txt: Any) -> str:
    """VIP/SVIP: chặn các dòng AI lỡ chốt đáp án/đáp số cuối."""
    t = clean(txt)
    if not t:
        return ""
    drop = re.compile(
        r"(?i)^\s*(?:[-*]\s*)?(?:đáp\s*án\s*cuối\s*cùng|đáp\s*án|kết\s*quả\s*cuối|chọn\s*[A-D]\b|vậy\s+đáp\s*án)\s*[:：]?.*$"
    )
    kept = [ln for ln in t.splitlines() if not drop.match(ln.strip())]
    out = "\n".join(kept).strip()
    out = re.sub(r"(?i)\n?\s*đáp\s*án\s*cuối\s*cùng\s*[:：][^\n]*", "", out).strip()
    return out or "Em làm theo các bước gợi ý, rồi tự so kết quả với lựa chọn trong đề."


def build_ai_assistant_note_prompt(q: Dict[str, Any], user_answer: Any = "") -> str:
    admin_mode = is_admin()
    block = build_ai_question_block(
        q, user_answer, include_sheet_answer=admin_mode, include_loigiai=False
    )
    dang = effective_dang(q)
    dang_bt = clean(q.get("DangBaiTap", "")) or "chưa gán"
    kind = subject_kind_from_mon(effective_question_mon(q)) or infer_subject_kind_from_question(q)
    unit_note = (
        "điều kiện xét (MXĐ, miền giá trị) và biến đổi tương đương"
        if kind == "math"
        else "đổi đơn vị SI và điều kiện áp dụng công thức"
    )
    ref_ans = assistant_format_final_answer(q) if admin_mode else ""
    rules = [
        "Bạn nhập vai: TRỢ LÝ AI THẦY MINH trong app luyện đề THPT.",
        (
            "Nhiệm vụ ADMIN: đọc đề, giải đủ bước và kết thúc bằng ĐÁP ÁN CUỐI CÙNG đúng loại câu (TN / Đ/S / TLN)."
            if admin_mode
            else "Nhiệm vụ VIP/SVIP: đọc đề và gợi ý CÁC BƯỚC LÀM để học sinh tự chọn đáp án; KHÔNG chốt đáp án cuối."
        ),
        "",
        *assistant_subject_rules(q),
        "",
        *assistant_dang_prompt_rules(dang),
        "",
        "QUY TẮC BẮT BUỘC:",
        "- Phân biệt rõ TN (một chữ A–D), Đ/S (mỗi ý Đúng/Sai), TLN (số/biểu thức) — không trộn cách chốt đáp án.",
        "- Được nêu công thức, thay số từng bước, lưu ý " + unit_note + " và bẫy dễ sai.",
        "- KHÔNG bịa đáp án — suy luận từ đề bài và phương án; nếu không chắc thì nêu bước kiểm tra.",
        "- Nếu có hình/đồ thị: đọc trục, giao điểm, cực trị, đơn vị trong hình.",
        "- Công thức đặt trong $...$ khi cần.",
    ]
    if admin_mode:
        rules.extend([
            "- Cuối bài BẮT BUỘC có dòng «Đáp án cuối cùng: …» khớp đáp án Sheet cột P.",
            f"- Đáp án tham chiếu Sheet (cột P): {ref_ans}",
        ])
        layout = assistant_note_layout_block(dang)
    else:
        rules.extend([
            "- VIP/SVIP: tuyệt đối không ghi «Đáp án cuối cùng», không nói A/B/C/D nào đúng, không nêu đáp số cuối.",
            "- Chỉ viết 2 mục: 1. PHƯƠNG HƯỚNG LÀM BÀI; 2. GỢI Ý TỰ KIỂM TRA.",
        ])
        layout = []
    return "\n".join([
        *rules,
        "",
        *layout,
        "",
        f"Dạng câu (effective): {dang} ({assistant_dang_code(dang)})",
        f"Dạng bài tập cột H: {dang_bt}",
        "DỮ LIỆU CÂU:",
        block,
    ])


def ai_assistant_note_from_provider(
    q: Dict[str, Any],
    user_answer: Any = "",
    *,
    force_provider: str = "",
    allow_gpt_fallback: bool = False,
) -> Tuple[str, int, str, str, str]:
    cfg = ai_runtime_config()
    last_error = ""

    if is_admin():
        sys_prompt = assistant_sys_prompt_for_question(q, chat=False)
        user_prompt = build_ai_assistant_note_prompt(q, user_answer)
        try:
            txt, used, model, idx = admin_ai_call_text(
                sys_prompt,
                user_prompt,
                max_tokens=ASSISTANT_NOTE_MAX_TOKENS,
                temp=0.15,
                timeout=35,
                force_provider=force_provider,
                allow_gpt_fallback=allow_gpt_fallback,
            )
            txt = _sanitize_assistant_note_text(txt)
            if txt:
                txt = assistant_ensure_final_answer_line(txt, q)
                return txt, idx, used, model, ""
        except AdminGeminiQuotaError:
            raise
        except Exception as e:
            last_error = clean(str(e))

    txt, idx, used, model, err = assistant_invoke_ai(
        q, user_answer, chat=False, max_tokens=ASSISTANT_NOTE_MAX_TOKENS
    )
    last_error = err or last_error
    if txt:
        return txt, idx, used, model, ""
    if not cfg.get("has_keys"):
        return assistant_no_keys_message(q), 0, "FALLBACK", "", last_error
    return (
        assistant_wrap_fallback_note(q, last_error),
        0,
        "FALLBACK",
        "",
        last_error or "AI chưa phản hồi",
    )

