@app.route("/api/learning/generate-save", methods=["POST"])
def api_learning_generate_save():
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được tạo và lưu học liệu."}), 403
    body = request.get_json(silent=True) or {}
    kind = "method" if clean(body.get("kind", "")).lower() == "method" else "theory"
    if kind == "theory":
        return jsonify({"error": "Lý thuyết SGK phải do ADMIN nhập/dán nội dung chuẩn được phép dùng rồi lưu vào sheet Ly_Thuyet; GPT không tự tạo Lý thuyết. GPT chỉ dùng cho Dạng bài tập và Phương pháp giải."}), 400
    q = _learning_question_from_body(body)
    prompt = _learning_ai_prompt(kind, q)
    try:
        force, allow = admin_ai_body_params(body)
        raw, provider, model = _learning_ai_call(
            prompt, force_provider=force, allow_gpt_fallback=allow
        )
    except AdminGeminiQuotaError as e:
        return admin_ai_quota_json(e)
    obj = _extract_ai_json_object(raw)
    if not obj:
        return jsonify({"error": "AI chưa trả JSON hợp lệ.", "raw": raw[:2000]}), 500
    item = _coerce_learning_item(kind, q, obj)
    st = get_store()
    res = st.save_learning_item(kind, item)
    res.update({"provider_used": provider, "model": model})
    dbt_item = clean(item.get("DangBaiTap", ""))
    if kind == "method" and dbt_item and not _is_bad_dangbaitap_value(dbt_item):
        scoped_sug, _ = _scoped_dangbaitap_suggestions(st, q, limit=50)
        dbt_item, _, _ = _resolve_dangbaitap_to_suggestions(dbt_item, scoped_sug)
        row_q = int(q.get("_row") or body.get("row") or 0)
        cur_dbt = clean(q.get("DangBaiTap", ""))
        if row_q >= 2 and (not cur_dbt or _is_bad_dangbaitap_value(cur_dbt)):
            try:
                upd = st.update_question(row_q, {"DangBaiTap": dbt_item}, clean(q.get("ID", "")))
                res["question_dangbaitap_updated"] = True
                res["question_row"] = upd.get("row", row_q)
                res["DangBaiTap"] = dbt_item
            except Exception as e:
                res["question_dangbaitap_error"] = str(e)
    return jsonify(res)

