@app.route("/api/admin/dbt-order", methods=["GET", "POST"])
def api_admin_dbt_order():
    """ADMIN: đọc/ghi thứ tự hiển thị Dạng BT theo MaDe (mục lục + modal làm bài)."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được sắp xếp thứ tự Dạng bài tập."}), 403
    if request.method == "GET":
        made = clean(request.args.get("made") or request.args.get("MaDe") or "")
        orders = load_dbt_orders()
        order = list(orders.get(made) or [])
        available: List[str] = []
        if made:
            try:
                st = get_store()
                if st.questions_loaded:
                    item = next((x for x in st.catalog if clean(x.get("MaDe")) == made), None)
                    if item:
                        fc = (item.get("FilterCounts") or {}).get("dangbaitap") or {}
                        if isinstance(fc, dict):
                            available = ordered_dbt_names(made, {k: int(v or 0) for k, v in fc.items()}, orders)
            except Exception:
                pass
        return jsonify({"ok": True, "made": made, "order": order, "available": available})
    body = request.get_json(silent=True) or {}
    made = clean(body.get("made") or body.get("MaDe") or "")
    raw_order = body.get("order") or body.get("names") or []
    if not made:
        return jsonify({"error": "Chưa có MaDe/chuyên đề."}), 400
    if not isinstance(raw_order, list):
        return jsonify({"error": "Danh sách thứ tự không hợp lệ."}), 400
    names = [clean(x) for x in raw_order if clean(x) and not _is_bad_dangbaitap_value(x)]
    try:
        st = get_store()
        st.ensure_questions_loaded()
        orders = save_dbt_order_one(made, names)
    except Exception as e:
        orders = load_dbt_orders()
        orders[made] = names
        save_dbt_orders(orders)
    return jsonify({"ok": True, "made": made, "order": names, "message": "Đã lưu thứ tự Dạng bài tập (Google Sheet DBT_ThuTu)."})




@app.route("/api/admin/dang-similarity", methods=["POST"])
def api_admin_dang_similarity():
    """ADMIN: phân tích độ giống câu hỏi / khung PP trong cùng dạng BT (ngưỡng 70%)."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được phân tích trùng dạng."}), 403
    body = request.get_json(silent=True) or {}
    st = get_store()
    st.ensure_questions_loaded()
    st.ensure_learning_loaded()
    try:
        threshold = float(body.get("threshold") or DANG_CONTENT_SIMILARITY_THRESHOLD)
    except Exception:
        threshold = DANG_CONTENT_SIMILARITY_THRESHOLD
    threshold = max(0.5, min(0.95, threshold))
    report = analyze_dang_content_similarity(
        st.questions,
        st.method_items,
        threshold=threshold,
        mon=clean(body.get("Mon") or body.get("mon") or ""),
        lop=clean(body.get("Lop") or body.get("lop") or ""),
        chuong=clean(body.get("Chuong") or body.get("chuong") or ""),
        baihoc=clean(body.get("BaiHoc") or body.get("baihoc") or ""),
        dangbaitap=clean(body.get("DangBaiTap") or body.get("dangbaitap") or ""),
        made=clean(body.get("MaDe") or body.get("made") or ""),
        question_id=clean(body.get("ID") or body.get("id") or body.get("question_id") or ""),
    )
    if body.get("with_ai") and report.get("pair_count"):
        try:
            force, allow = admin_ai_body_params(body)
            report["ai_advice"] = ai_dang_similarity_advice(
                report, force_provider=force, allow_gpt_fallback=allow
            )
        except AdminGeminiQuotaError as e:
            return admin_ai_quota_json(e)
        except Exception as e:
            report["ai_advice_error"] = str(e)
    return jsonify(report)

@app.route("/api/admin/dbt-review-dup-scan", methods=["POST"])
def api_admin_dbt_review_dup_scan():
    """ADMIN: quét trùng ID/nội dung trong danh sách dòng đang duyệt Dạng BT."""
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN."}), 403
    body = request.get_json(silent=True) or {}
    rows_in = body.get("rows") or []
    if not isinstance(rows_in, list):
        return jsonify({"error": "Thiếu danh sách dòng Sheet."}), 400
    row_set = sorted({int(r) for r in rows_in if int(r or 0) > 1})
    if not row_set:
        return jsonify({"marks": {}, "copy_count": 0, "group_count": 0})
    try:
        st = get_store()
        st.ensure_questions_loaded()
        want = set(row_set)
        subset = [q for q in st.questions if int(q.get("_row") or 0) in want]
        plan = plan_sheet_duplicate_removals(subset)
        marks: Dict[str, Any] = {}
        for cluster in plan.get("clusters") or []:
            if len(cluster) < 2:
                continue
            keep = cluster[0]
            for r in cluster:
                if r not in want:
                    continue
                marks[str(r)] = {
                    "dup_type": "content",
                    "dup_keep": r == keep,
                    "dup_rows": cluster,
                }
        copy_count = sum(1 for m in marks.values() if not m.get("dup_keep"))
        group_count = sum(
            1 for c in (plan.get("clusters") or [])
            if len(c) >= 2 and any(r in want for r in c)
        )
        return jsonify({
            "marks": marks,
            "copy_count": copy_count,
            "group_count": group_count,
            "samples": (plan.get("samples") or [])[:8],
        })
    except Exception as e:
        return jsonify({"error": str(e)}), 400

