@app.route("/api/latex/import", methods=["POST"])
def api_latex_import():
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN được nhập LaTeX vào Google Sheet"}), 403

    asset_zip = None
    level_overrides: Any = []
    ai_level_explicit: Any = None
    ai_body: Dict[str, Any] = {}
    if request.content_type and "multipart/form-data" in request.content_type:
        tex = request.form.get("tex", "")
        try:
            defaults = json.loads(request.form.get("defaults", "{}") or "{}")
        except Exception:
            defaults = {}
        commit = str(request.form.get("commit", "false")).lower() in ("1", "true", "yes", "on")
        ai_level_explicit = request.form.get("ai_level", "")
        try:
            level_overrides = json.loads(request.form.get("level_overrides", "[]") or "[]")
        except Exception:
            level_overrides = []
        asset_zip = request.files.get("assets_zip")
        ai_body = {
            "admin_ai_provider": request.form.get("admin_ai_provider", ""),
            "admin_ai_allow_gpt_fallback": request.form.get("admin_ai_allow_gpt_fallback", ""),
        }
    else:
        body = request.get_json(silent=True) or {}
        tex = body.get("tex", "")
        defaults = body.get("defaults") or {}
        commit = str(body.get("commit", "false")).lower() in ("1", "true", "yes", "on")
        ai_level_explicit = body.get("ai_level")
        level_overrides = body.get("level_overrides") or []
        ai_body = body

    if not clean(tex):
        return jsonify({"error": "Chưa có nội dung LaTeX."}), 400
    if len(str(tex)) > 900_000:
        return jsonify({"error": "File LaTeX quá lớn. Hãy chia nhỏ rồi nhập từng phần."}), 400

    try:
        ai_level = _latex_ai_level_requested(defaults, ai_level_explicit)
        defaults_for_parse = dict(defaults or {})
        if ai_level:
            # Không để giá trị "AI" bị ghi thẳng vào cột MucDo.
            defaults_for_parse["MucDo"] = ""
        asset_ctx = _build_latex_asset_context(commit, assets_zip=asset_zip)
        parsed = parse_latex_questions_2026(str(tex), defaults_for_parse, asset_ctx=asset_ctx)
        theory_groups = parse_latex_theory_groups_2026(str(tex), defaults_for_parse)
        theory_lessons = parse_latex_lesson_theory_2026(str(tex), defaults_for_parse)
        ai_meta: Dict[str, Any] = {"ai_level": ai_level, "ai_level_done": False, "ai_model": "", "ai_provider": "OPENAI", "ai_level_error": "", "warnings": []}
        override_count = _apply_latex_level_overrides(parsed.get("questions", []), level_overrides)
        if ai_level and not override_count:
            try:
                force, allow = admin_ai_body_params(ai_body)
                ai_meta = admin_gpt_classify_latex_levels(
                    parsed.get("questions", []),
                    force_provider=force,
                    allow_gpt_fallback=allow,
                )
            except AdminGeminiQuotaError as e:
                return admin_ai_quota_json(e)
        elif override_count:
            ai_meta.update({"ai_level_done": False, "ai_level_error": "", "override_count": override_count})
        if ai_meta.get("warnings"):
            parsed.setdefault("warnings", [])
            for w in ai_meta.get("warnings", [])[:10]:
                parsed["warnings"].append({"index": 0, "warning": clean(w)})
        if not commit:
            # Trả đầy đủ danh sách câu đã tách để ADMIN xem ngay trên modal,
            # không phải nhìn một chuỗi text dính nhau.
            preview_questions = []
            warn_by_index = {int(w.get("index") or 0): clean(w.get("warning") or w.get("reason") or "") for w in (parsed.get("warnings", []) or []) if isinstance(w, dict)}
            for idx, q in enumerate(parsed.get("questions", [])[:200], start=1):
                preview_questions.append({
                    "index": idx,
                    "ID": q.get("ID", ""),
                    "MaDe": q.get("MaDe", ""),
                    "Dang": q.get("Dang", ""),
                    "MucDo": q.get("MucDo", ""),
                    "_AiMucDo": q.get("_AiMucDo", ""),
                    "_AiConfidence": q.get("_AiConfidence", ""),
                    "_AiReason": q.get("_AiReason", ""),
                    "CauHoi": q.get("CauHoi", ""),
                    "A": q.get("A", ""),
                    "B": q.get("B", ""),
                    "C": q.get("C", ""),
                    "D": q.get("D", ""),
                    "DapAn": q.get("DapAn", ""),
                    "SaiSo": q.get("SaiSo", ""),
                    "LoiGiai": q.get("LoiGiai", ""),
                    "HinhAnh": q.get("HinhAnh", ""),
                    "warning": warn_by_index.get(idx, ""),
                })
            return jsonify({
                "ok": True,
                "dry_run": True,
                "total_blocks": parsed.get("total_blocks", 0),
                "parsed": parsed.get("parsed", 0),
                "counts": parsed.get("counts", {}),
                "warnings": parsed.get("warnings", [])[:30],
                "media": parsed.get("media", {}),
                "ai_level": ai_meta.get("ai_level", False),
                "ai_level_done": ai_meta.get("ai_level_done", False),
                "ai_provider": ai_meta.get("ai_provider", "OPENAI"),
                "ai_model": ai_meta.get("ai_model", ""),
                "ai_level_error": ai_meta.get("ai_level_error", ""),
                "override_count": ai_meta.get("override_count", 0),
                "questions": preview_questions,
                "sample": preview_questions[:8],
                "theory_groups_count": len(theory_groups),
                "theory_groups": [
                    {
                        "ID": it.get("ID", ""),
                        "DangBaiTap": it.get("DangBaiTap", ""),
                        "NoiDungLaTeX": it.get("NoiDungLaTeX", ""),
                    }
                    for it in theory_groups[:30]
                ],
                "theory_lessons_count": len(theory_lessons),
                "theory_lessons": [
                    {
                        "ID": it.get("ID", ""),
                        "Chuong": it.get("Chuong", ""),
                        "BaiHoc": it.get("BaiHoc", ""),
                        "TieuDe": it.get("TieuDe", ""),
                        "NoiDungLaTeX": it.get("NoiDungLaTeX", ""),
                    }
                    for it in theory_lessons[:30]
                ],
            })

        st = get_store()
        st.ensure_questions_loaded()
        res = st.add_questions_bulk(parsed.get("questions", []))
        theory_saved: List[Dict[str, Any]] = []
        theory_errors: List[str] = []
        lesson_saved: List[Dict[str, Any]] = []
        lesson_errors: List[str] = []
        for theory_item in theory_groups:
            try:
                saved = st.save_learning_item("method", theory_item)
                theory_saved.append({
                    "row": saved.get("row"),
                    "action": saved.get("action"),
                    "DangBaiTap": theory_item.get("DangBaiTap", ""),
                })
            except Exception as exc:
                theory_errors.append(f"{theory_item.get('DangBaiTap', '')}: {exc}")
        for lesson_item in theory_lessons:
            try:
                saved = st.save_learning_item("theory", lesson_item)
                lesson_saved.append({
                    "row": saved.get("row"),
                    "action": saved.get("action"),
                    "BaiHoc": lesson_item.get("BaiHoc", ""),
                    "Chuong": lesson_item.get("Chuong", ""),
                })
            except Exception as exc:
                lesson_errors.append(f"{lesson_item.get('BaiHoc', '')}: {exc}")
        res.update({
            "dry_run": False,
            "total_blocks": parsed.get("total_blocks", 0),
            "parsed": parsed.get("parsed", 0),
            "counts": parsed.get("counts", {}),
            "warnings": parsed.get("warnings", [])[:30],
            "media": parsed.get("media", {}),
            "ai_level": ai_meta.get("ai_level", False),
            "ai_level_done": ai_meta.get("ai_level_done", False),
            "ai_provider": ai_meta.get("ai_provider", "OPENAI"),
            "ai_model": ai_meta.get("ai_model", ""),
            "ai_level_error": ai_meta.get("ai_level_error", ""),
            "override_count": ai_meta.get("override_count", 0),
            "theory_groups_count": len(theory_groups),
            "theory_saved": theory_saved,
            "theory_errors": theory_errors,
            "theory_lessons_count": len(theory_lessons),
            "theory_lessons_saved": lesson_saved,
            "theory_lessons_errors": lesson_errors,
        })
        return jsonify(res)
    except Exception as e:
        return jsonify({"error": str(e)}), 400


@app.route("/api/img/drive/<path:file_ref>")
def api_drive_image(file_ref: str):
    """Proxy ảnh Google Drive — lh3.googleusercontent không nhúng được trong <img>."""
    fid = extract_drive_file_id(file_ref) or clean(file_ref)
    if not fid or len(fid) < 12:
        return "ID ảnh không hợp lệ", 404
    try:
        token = _google_access_token()
        req = urllib.request.Request(
            f"https://www.googleapis.com/drive/v3/files/{fid}?alt=media",
            headers={"Authorization": f"Bearer {token}"},
        )
        with urllib.request.urlopen(req, timeout=45) as resp:
            data = resp.read()
        if not data:
            raise ValueError("empty image")
        ct = resp.headers.get("Content-Type") or _guess_image_mime(data, fid)
        out = make_response(data)
        out.headers["Content-Type"] = ct
        out.headers["Cache-Control"] = "public, max-age=86400"
        return out
    except Exception:
        return redirect(_drive_thumbnail_fallback_url(fid), code=302)


@app.route("/api/admin/drive-images-setup", methods=["GET"])
def api_admin_drive_images_setup():
    bad = require_login_json()
    if bad:
        return bad
    if not is_admin():
        return jsonify({"error": "Chỉ ADMIN."}), 403
    folder_id = ""
    folder_err = ""
    upload_ok = False
    upload_err = ""
    inspect: Optional[Dict[str, Any]] = None
    inspect_err = ""
    sa_role = ""
    sa_role_err = ""
    try:
        global _DRIVE_UPLOAD_FOLDER_CACHE
        _DRIVE_UPLOAD_FOLDER_CACHE = ""
        folder_id = _drive_upload_folder_id()
        if not folder_id:
            folder_err = "Chưa tìm thấy thư mục"
        else:
            inspect, inspect_err = _drive_folder_inspect(folder_id)
            sa_role, sa_role_err = _drive_sa_folder_role(folder_id)
            upload_ok, upload_err = _drive_test_upload()
    except Exception as e:
        folder_err = _drive_api_error_detail(e)
    fix_hint = _drive_upload_fix_hint(upload_err or inspect_err or sa_role_err or folder_err)
    return jsonify({
        "ok": bool(upload_ok),
        "folder_accessible": bool(inspect),
        "can_add_children": bool((inspect or {}).get("can_add_children")),
        "sa_role": sa_role,
        "sa_role_error": sa_role_err,
        "folder_drive_name": clean((inspect or {}).get("name", "")),
        "service_account_email": _google_service_account_email(),
        "folder_name": _drive_folder_display_name(),
        "folder_id": folder_id,
        "folder_url": f"https://drive.google.com/drive/folders/{folder_id}" if folder_id else "",
        "inspect_error": inspect_err,
        "upload_error": upload_err,
        "fix_hint": fix_hint,
        "gas_configured": _gas_upload_configured(),
        "gas_script": GAS_DRIVE_UPLOAD_SCRIPT,
        "hint": fix_hint or upload_err or inspect_err or _drive_setup_hint(folder_err) if (folder_err or not upload_ok) else _drive_setup_hint(),
    })


@app.route("/api/tikz/render", methods=["POST"])
def api_tikz_render():
    """Biên dịch TikZ (hoặc tikzraw:…) thành PNG để hiển thị đồ thị khi làm bài."""
    body = request.get_json(silent=True) or {}
    src = clean(body.get("src", body.get("tikz", body.get("HinhAnh", ""))))
    tikz_code = _decode_tikzraw_src(src)
    if not tikz_code or "tikzpicture" not in tikz_code.lower():
        return jsonify({"ok": False, "error": "Không có mã TikZ hợp lệ."}), 400
    cached = _tikz_cache_png_url(tikz_code)
    if cached:
        return jsonify({"ok": True, "url": cached, "cached": True})
    ctx = _build_latex_asset_context(commit=True)
    url = _compile_tikz_to_png(tikz_code, ctx, 1, 1)
    if url:
        return jsonify({"ok": True, "url": url, "cached": bool(_tikz_cache_png_url(tikz_code))})
    warn = ""
    for w in (ctx.get("warnings") or []):
        warn = clean(w.get("warning", ""))
        if warn:
            break
    return jsonify({"ok": False, "error": warn or "Chưa biên dịch được TikZ."}), 500


