@app.route("/service-worker.js")
def pwa_service_worker():
    js = """
const CACHE_NAME = 'luyen-de-ai-v321-cartoon-teacher-icon';
const CORE_ASSETS = ['/manifest.json','/pwa-icon-192.png','/pwa-icon-512.png','/offline'];
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache =>
      Promise.all(CORE_ASSETS.map(u => cache.add(u).catch(() => null)))
    ).then(() => self.skipWaiting())
  );
});
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== CACHE_NAME).map(k => caches.delete(k)))
    ).then(() => self.clients.claim())
  );
});
self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});
self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;
  /* Không chặn tải trang HTML — tránh báo \"mất mạng\" giả khi mạng chậm/Render cold start */
  if (req.mode === 'navigate' || req.destination === 'document') return;
  if (CORE_ASSETS.includes(url.pathname)) {
    event.respondWith(
      caches.match(req).then(cached => cached || fetch(req).catch(() => caches.match('/offline')))
    );
  }
});
"""
    return app.response_class(js, mimetype="application/javascript; charset=utf-8")

@app.errorhandler(Exception)
def handle_error(e):
    return jsonify({"error": str(e)}), 500

def _schedule_store_warmup() -> None:
    """Nạp Google Sheet ngay khi worker Gunicorn khởi động — giảm chờ lần đầu user vào app."""
    if not os.environ.get("GOOGLE_SHEET_ID", "").strip():
        return

    def _run():
        time.sleep(0.3)
        try:
            get_store().start_questions_background(force=False)
        except Exception:
            pass

    threading.Thread(target=_run, daemon=True).start()


_schedule_store_warmup()

if __name__ == "__main__":
    port = int(os.environ.get("PORT", "8000"))
    app.run(host="0.0.0.0", port=port, debug=False)









